insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('klassik', 'Klassik', '', '', '', '', 'Klassik', '[{"kategorie": "hist.", "text": "\"kulturelle und künstlerische Epoche, die grob von der Mitte des 18. Jahrhunderts bis zum frühen 19. Jahrhundert reicht\""}, {"kategorie": "", "text": "Sie zeichnet sich durch die Rückbesinnung auf die Ideale der antiken Kunst und Kultur aus, wie Harmonie, Ausgewogenheit, Klarheit und Vernunft. Diese Prinzipien prägten sowohl die Literatur und bildende Kunst als auch die Musik"}, {"kategorie": "", "text": "Im musikalischen Bereich spricht man oft von der [[Wiener]] Klassik, die durch Komponisten wie Haydn, Mozart und Beethoven weltweit bekannt wurde und Wien zum Zentrum der musikalischen Entwicklung in dieser Epoche machte"}, {"kategorie": "", "text": "Merkmale der Klassik: (i) Harmonie und Ausgewogenheit (in der Kunst und Musik der Klassik stehen klare Strukturen, Symmetrie und Ausgewogenheit im Vordergrund. Man strebte nach einer harmonischen Verbindung von Form und Inhalt), (ii) Vernunft und Klarheit (die Klassik steht im Gegensatz zur Emotionalität und Individualität der späteren [[Romantik]] und betont stattdessen Ordnung, Vernunft und logische Klarheit, insbesondere in der Musik und Dichtung), (iii) Antikenrezeption (die Kunst und Architektur der Klassik orientierte sich an den Vorbildern der griechischen und römischen Antike, die als Höhepunkt der kulturellen Entwicklung angesehen wurden)"}, {"kategorie": "", "text": "Wien war in der Epoche der Klassik das musikalische und kulturelle Zentrum Europas. Die [[Wiener]] Klassik bezeichnet die Blütezeit der Musik, die durch die Werke von Joseph Haydn, Wolfgang Amadeus Mozart und Ludwig van Beethoven repräsentiert wird"}, {"kategorie": "", "text": "Wien zog in dieser Zeit Musiker und Komponisten aus ganz Europa an, die die Stadt zu einem kulturellen Mittelpunkt machten. In den Adelshäusern, Theatern und Salons Wiens wurden die Werke dieser großen Komponisten aufgeführt, und Musik wurde ein zentraler Bestandteil des gesellschaftlichen Lebens"}, {"kategorie": "", "text": "In der Architektur orientierte sich die Klassik an den klaren und symmetrischen Formen der Antike. In Wien entstanden repräsentative Bauwerke im [[klassizistischen]] Stil, die durch ihre strenge Geometrie und Schlichtheit auffielen. Beispiele dafür sind der Ausbau der [[Hofburg]] und der Bau des [[Theseustempels]] im [[Volksgarten]]."}]'::jsonb, ''),
  ('deismus', 'Deismus', '', '', '', '', 'Deismus', '[{"kategorie": "hist.", "text": "\"religiös-philosophische Strömung, die während der [[Aufklärung]] im 17. und 18. Jahrhundert populär wurde\""}, {"kategorie": "", "text": "Der Deismus erkennt die Existenz eines Schöpfergottes an, der das Universum und die Naturgesetze erschaffen hat, sich jedoch nach der Schöpfung nicht mehr aktiv in das Geschehen der Welt einmischt"}, {"kategorie": "", "text": "Im Gegensatz zu den traditionellen Religionen lehnt der Deismus göttliche Offenbarungen, Wunder und die Vorstellung eines persönlichen Gottes, der in das menschliche Leben eingreift, ab"}, {"kategorie": "", "text": "Hauptmerkmale des Deismus: (i) Gott als Schöpfer (Deisten glauben an einen Gott, der die Welt geschaffen hat, aber danach keinen Einfluss mehr auf sie nimmt. Der Schöpfer wird als eine rationale, ordnende Kraft verstanden, die das Universum nach festen Naturgesetzen eingerichtet hat), (ii) Vernunft und Naturgesetze (Deisten vertrauen auf die menschliche Vernunft und die Erkenntnis der Naturgesetze, um die Welt und ihre Funktionsweise zu erklären. Religion wird dabei eher als eine ethische und moralische Orientierung gesehen, nicht als ein System von Dogmen oder Offenbarungen), (iii) Ablehnung von Wundern und Offenbarungen: (im Deismus wird die Vorstellung von göttlichen Eingriffen, Wundern oder einer besonderen göttlichen Offenbarung, wie sie in den monotheistischen Religionen (Christentum, Judentum, Islam) vorkommen, abgelehnt)"}, {"kategorie": "", "text": "In Wien wurde der Deismus vor allem im Kontext der [[Aufklärung]] und des [[aufgeklärten]] Absolutismus diskutiert. Die Ideen des Deismus fanden Anklang bei Intellektuellen, Philosophen und Vertretern des Bürgertums, die sich von den strengen kirchlichen Dogmen und der engen Verbindung zwischen Kirche und Staat lösen wollten"}, {"kategorie": "", "text": "Unter der Herrschaft von Kaiser [[Joseph]] II. (1765–1790) wurden die Ideen der Aufklärung, einschließlich des Deismus, gefördert. Joseph II. verfolgte eine Politik der Säkularisierung und religiösen Toleranz, wie durch das [[Toleranzpatent]] von 1781, das Protestanten, Orthodoxen und Juden mehr Rechte gewährte. Obwohl Joseph selbst Katholik war, spiegelten viele seiner Reformen den Geist des Deismus wider, da sie auf Vernunft und staatliche Kontrolle über religiöse Angelegenheiten setzten."}]'::jsonb, ''),
  ('absolutismus', 'Absolutismus', '', '', '', '', 'Absolutismus', '[{"kategorie": "hist.", "text": "\"Regierungsform, die vom späten 16. bis ins 18. Jahrhundert in Europa verbreitet war\""}, {"kategorie": "", "text": "Dabei lag die gesamte Macht im Staat bei einem Monarchen, der als uneingeschränkter Herrscher regierte. Der König oder Kaiser beanspruchte seine Autorität als von Gott gegeben ([[Gottesgnadentum]]) und war nicht durch Parlamente oder andere Institutionen beschränkt. Gesetze, Verwaltung und Politik wurden zentral vom Herrscher kontrolliert, und der Adel sowie die Kirche waren seiner Macht untergeordnet"}, {"kategorie": "", "text": "Merkmale des Absolutismus: (i) zentralisierte Macht (der Monarch hatte die alleinige Entscheidungsgewalt über Gesetze, Steuern, das Militär und die Außenpolitik), (ii) Gottesgnadentum (der Herrscher legitimierte seine Macht als von Gott gegeben, was ihn über weltliche Institutionen stellte; (iii) staatliche Kontrolle (Verwaltung, Justiz und Militär wurden stark zentralisiert und standen direkt unter der Kontrolle des Herrschers. Beamte und Minister wurden vom Monarchen ernannt)"}, {"kategorie": "", "text": "In Wien war der Absolutismus eng mit der Herrschaft der Habsburger verbunden, die vom 16. bis zum 18. Jahrhundert über große Teile Europas herrschten. Der [[Wiener]] Hof entwickelte sich zu einem der wichtigsten Zentren des europäischen Absolutismus, insbesondere unter den Kaisern [[Leopold]] I. (regierte 1658–1705) und [[Maria]] Theresia (regierte 1740–1780). Die [[Habsburger]] nutzten den Absolutismus, um ihre Macht innerhalb der Monarchie zu festigen und den Einfluss der Kirche und des Adels zu kontrollieren"}, {"kategorie": "", "text": "Leopold I. war ein typischer Vertreter des Barockabsolutismus. Unter seiner Herrschaft wurde Wien zu einem glanzvollen Zentrum absolutistischer Macht. Leopold I. führte mehrere Kriege gegen das Osmanische Reich und Frankreich, was seine Machtstellung innerhalb Europas festigte.\nLeopold baute den [[Wiener]] Hof aus und förderte die barocke Prachtentfaltung in Kunst und Architektur, um seine Macht symbolisch darzustellen"}, {"kategorie": "", "text": "Der [[Wiener]] Hof war das Zentrum der Macht in der [[Habsburgermonarchie]] und spiegelte die Prinzipien des Absolutismus wider. Die Monarchen residierten im [[Hofburg-Palast]], der als symbolisches Zentrum ihrer absoluten Herrschaft diente. Der Hof war ein Ort des Prachtentfaltung, wo Kunst und Architektur dazu genutzt wurden, den Glanz und die Macht des Herrschers zu demonstrieren"}, {"kategorie": "", "text": "Der Absolutismus in Wien endete allmählich mit dem Aufkommen des [[aufgeklärten]] Absolutismus unter [[Joseph]] II., der die Ideen der Aufklärung mit der absoluten Herrschaft verband. Auch die politischen Umwälzungen der Französischen Revolution und die darauf folgenden Reformbewegungen in Europa führten dazu, dass die absolutistische Regierungsform im 19. Jahrhundert allmählich abgelöst wurde."}]'::jsonb, ''),
  ('gottesgnadentum', 'Gottesgnadentum', '', '', '', '', 'Gottesgnadentum', '[{"kategorie": "allg.", "text": "\"lateinisch \"Dei gratia\" bezeichnet die Vorstellung, dass ein Monarch seine Herrschaft unmittelbar von Gott erhält und deshalb niemandem außer Gott Rechenschaft schuldig ist\""}, {"kategorie": "", "text": "Diese Idee diente in vielen monarchischen Regimen, insbesondere während des [[Absolutismus]], als Legitimation für die uneingeschränkte, absolute Macht des Herrschers"}, {"kategorie": "", "text": "Der Monarch galt als von Gott eingesetzt und dadurch befugt, über sein Volk zu regieren, ohne durch Parlamente, Gesetze oder andere weltliche Institutionen eingeschränkt zu werden"}, {"kategorie": "", "text": "Merkmale des Gottesgnadentums: (i) göttliche Legitimation (die Herrscher leiteten ihre Macht direkt von Gott ab und sahen sich als dessen Stellvertreter auf Erden. Dies verlieh ihrer Herrschaft eine sakrale Autorität), (ii) unbeschränkte Macht (im Rahmen des Gottesgnadentums wurde die Macht des Monarchen als uneingeschränkt betrachtet. Er war allein Gott verpflichtet und niemandem sonst rechenschaftspflichtig), (iii) Stärkung der Monarchie (das Gottesgnadentum wurde besonders im [[Absolutismus]] als Rechtfertigung für die starke Zentralisierung der Macht und die Alleinherrschaft verwendet)"}, {"kategorie": "", "text": "In der [[Habsburgermonarchie]] spielte das Gottesgnadentum eine zentrale Rolle zur Legitimation der Herrschaft. Die Habsburger Kaiser sahen sich als von Gott auserwählt, das [[Heilige]] Römische Reich und später die [[österreichischen]] Erblande zu regieren"}, {"kategorie": "", "text": "[[Karl]] VI. und seine Tochter [[Maria]] Theresia stützten ihre Macht auf das Gottesgnadentum und festigten damit ihren Anspruch auf unbeschränkte Herrschaft in Wien und im Reich. Auch Kaiser [[Leopold]] I. (regierte 1658–1705) nutzte das Gottesgnadentum, um seine Macht zu legitimieren und gegen innenpolitische sowie außenpolitische Herausforderungen zu verteidigen."}]'::jsonb, ''),
  ('epitaph', 'Epitaph', '', '', '', '', 'Epitaph', '[{"kategorie": "allg.", "text": "\"Gedenkstein oder eine Gedenktafel, die meist an der Wand oder im Innenraum von Kirchen angebracht ist und an eine verstorbene Person erinnert\""}, {"kategorie": "", "text": "Ursprünglich diente das Epitaph dazu, das Andenken an den Verstorbenen zu ehren, oft durch Inschriften, bildliche Darstellungen oder kunstvolle Verzierungen"}, {"kategorie": "", "text": "Im Gegensatz zu einem Grabstein, der direkt über einem Grab errichtet wird, ist ein Epitaph nicht immer mit einer Grabstätte verbunden"}, {"kategorie": "", "text": "Merkmale eines Epitaphs: (i) Inschrift (enthält meist den Namen, das Geburts- und Sterbedatum sowie oft auch eine kurze Würdigung des Verstorbenen, manchmal in Form eines Bibelzitats oder eines Gedichts), (ii) kunstvolle Gestaltung (viele Epitaphe sind reich verziert mit Wappen, Symbolen des Glaubens (z. B. Kreuzen) oder Darstellungen des Verstorbenen), (iii) Platzierung (Epitaphe befinden sich typischerweise in Kirchen oder an Kirchenwänden, oft nahe dem Altar oder in Kapellen)"}, {"kategorie": "", "text": "Epitaphe wurden vor allem im Mittelalter, in der [[Renaissance]] und im [[Barock]] verwendet, um bedeutende Persönlichkeiten, wie Adlige, Kirchenmänner oder wohlhabende Bürger, zu ehren. In vielen Kirchen in Europa sind Epitaphe noch heute gut erhalten und dienen als wichtige Zeugnisse historischer Persönlichkeiten und Kunstwerke."}]'::jsonb, ''),
  ('portikus', 'Portikus', '', '', '', '', 'Portikus', '[{"kategorie": "arch.", "text": "\"architektonisches Element, das aus einer Reihe von Säulen besteht, die ein Dach tragen und einen Vorbau vor dem Eingang eines Gebäudes bilden\""}, {"kategorie": "", "text": "Der Portikus findet sich oft in repräsentativen Bauwerken und dient sowohl einem ästhetischen als auch einem funktionalen Zweck, indem er den Eingangsbereich betont und zugleich Schutz vor Witterung bietet"}, {"kategorie": "", "text": "Merkmale eines Portikus: (i) Säulenreihe (der Portikus wird durch eine oder mehrere Reihen von Säulen gestützt, die typischerweise klassische Säulenordnungen (dorisch, ionisch oder korinthisch) aufweisen), (ii) Überdachung (die Säulen tragen ein Dach oder ein Gebälk, das oft mit einem Dreiecksgiebel (Tympanon) versehen ist, ähnlich wie in antiken Tempeln), (iii) Eingangsbetonung (ein Portikus betont den Haupteingang eines Gebäudes und verleiht diesem monumentale Wirkung)"}, {"kategorie": "", "text": "Der Portikus ist besonders typisch für die griechische und römische Tempelarchitektur (z.B. das Pantheon in Rom)"}, {"kategorie": "", "text": "Aber auch in späteren Epochen, insbesondere im [[Klassizismus]] und in der [[Renaissance]], wurde der Portikus häufig in öffentlichen Gebäuden, Schlössern und Kirchen verwendet, um deren Eingangsbereich hervorzuheben"}, {"kategorie": "", "text": "Ein bekanntes Beispiel für einen Portikus in Wien ist das [[Parlament]]. Der Hauptbau des Parlamentsgebäudes wird durch einen imposanten Portikus mit korinthischen Säulen und einem klassischen Giebel geprägt, was die antiken Ideale von Demokratie und Rechtsstaatlichkeit symbolisiert"}, {"kategorie": "", "text": "Zusammengefasst ist ein Portikus ein architektonischer Säulenvorbau, der oft in repräsentativen Bauten verwendet wird, um den Eingangsbereich hervorzuheben und dem Gebäude eine monumentale Wirkung zu verleihen."}]'::jsonb, ''),
  ('rokoko', 'Rokoko', '', '', '', '', 'Rokoko', '[{"kategorie": "hist.", "text": "\"kunsthistorischer Stil, der sich im frühen 18. Jahrhundert aus dem [[Barock]] entwickelte und bis etwa 1770 populär war\""}, {"kategorie": "", "text": "Das Rokoko zeichnet sich durch seine verspielte, leichte und dekorative Ästhetik aus, im Gegensatz zum ernsteren und schwereren Barock."}, {"kategorie": "", "text": "Der Rokokostil fand in der Architektur, Malerei, Bildhauerei, Innenausstattung und im Kunstgewerbe Anwendung und betonte Eleganz, Zierlichkeit und feine Verzierungen. Die Motive sind oft asymmetrisch, organisch und voller geschwungener Linien und Ornamente"}, {"kategorie": "", "text": "Merkmale des Rokoko: (i) verspielte Dekoration (typisch sind zarte Verzierungen wie Muschelformen, Blumengirlanden, [[Rocaillen]] (Muschel- und Felsornamente) und feine, asymmetrische Ornamente), (ii) Leichtigkeit und Eleganz (der Rokoko-Stil wirkt oft leicht und heiter, mit Pastellfarben, viel Licht und filigranen Details), (iii) Asymmetrie (im Gegensatz zur Symmetrie des Barock setzte das Rokoko auf asymmetrische Muster und schwungvolle Linien, was dem Stil eine spielerische Dynamik verleiht), (iv) Sinnlichkeit (der Stil betont häufig weltliche, sinnliche Themen, wie Szenen des Liebeslebens, Feste und pastorale Landschaften)"}, {"kategorie": "", "text": "In Wien erreichte der Rokoko-Stil vor allem in der Architektur und Innenausstattung seinen Höhepunkt und prägte das Stadtbild in der ersten Hälfte des 18. Jahrhunderts. Der Wiener Adel und die Habsburger Monarchie setzten den Rokoko-Stil ein, um ihren Machtanspruch zu repräsentieren, jedoch auf eine leichtere und weniger monumentale Weise als im Barock"}, {"kategorie": "", "text": "Ein herausragendes Beispiel für den Rokokostil in Wien ist die Innenausstattung des [[Schlosses]] Schönbrunn. Obwohl das Schloss in seiner Gesamtstruktur barock ist, zeigt die Innenausstattung vor allem in den kaiserlichen Gemächern den eleganten Rokoko-Stil. Feine Stuckverzierungen, zarte Farben und kunstvolle Wanddekorationen mit Pastelltönen und Gold sind charakteristisch für diesen Stil"}, {"kategorie": "", "text": "Der Obere Belvedere, ein weiteres Meisterwerk der Wiener Architektur, weist ebenfalls Elemente des Rokoko auf, vor allem in den Innenräumen und der kunstvollen Dekoration"}, {"kategorie": "", "text": "Viele Adelsresidenzen und Palais in Wien wurden im Rokoko-Stil eingerichtet, wobei die Innenräume durch kunstvolle Stuckarbeiten, Spiegel, Kristallleuchter und aufwendige Wandbespannungen geprägt wurden"}, {"kategorie": "", "text": "Franz Anton Maulbertsch und Johann Michael Rottmayr waren bekannte Rokoko-Maler, die Fresken in Wiener Kirchen und Palästen schufen. Ihre Arbeiten zeichnen sich durch helle Farben, bewegte Kompositionen und oft sinnliche Themen aus"}, {"kategorie": "", "text": "Die Bildhauerei und Innenraumkunst blühte mit Meistern wie Georg Raphael Donner, dessen Werke das Rokoko in seiner eleganten und verspielten Form in Wien verkörpern (siehe [[Donnerbrunnen]])"}, {"kategorie": "", "text": "Der Name Rokoko leitet sich vom französischen Wort [[rocaille]] ab, das wörtlich „Muschelwerk“ bedeutet. Dieses Wort bezieht sich auf die dekorativen Motive, die oft Muschelformen, Fels- und Pflanzenmotive nachahmen und typisch für die Verzierungen dieser kunsthistorischen Epoche sind. Zusammengefasst bedeutet Rokoko also \"Muschelstil\" oder \"Muschelwerk\"."}]'::jsonb, ''),
  ('rocaille', 'Rocaille', '', '', '', '', 'Rocaille', '[{"kategorie": "arch.", "text": "\"zentrales Dekorationselement des [[Rokoko]], das sich durch asymmetrische, geschwungene und organische Formen auszeichnet\""}, {"kategorie": "", "text": "Der Begriff stammt aus dem Französischen und bedeutet \"Muschelwerk\" oder \"Felsgestein\", da die Rocaille ursprünglich aus muschelartigen und felsigen Motiven entwickelt wurde. Rocaille-Ornamente wurden in der Architektur, im Kunsthandwerk und in der Innenraumgestaltung verwendet und gaben dem Rokoko seinen charakteristischen verspielten, dekorativen Stil"}, {"kategorie": "", "text": "Besonders in Schlössern und Palais wurden im Rokoko Rocaille-Verzierungen an Decken, Wänden und Möbeln verwendet. Sie schmücken beispielsweise auch viele Räume des [[Schlosses]] Schönbrunn"}, {"kategorie": "", "text": "Rocaille-Formen wurden auch auf Möbelstücke, Porzellan und Goldschmiedearbeiten übertragen, oft in Kombination mit floralen Motiven und Pastelltönen"}, {"kategorie": "", "text": "In der Architektur wurden Rocaille-Ornamente in Stuckarbeiten integriert, um Innenräume reich zu verzieren"}, {"kategorie": "", "text": "Die Rocaille ist ein typisches und dekoratives Element des Rokoko-Stils und war für diesen auch namensgebend. Denn \"Rokoko\" leitet sich direkt von \"rocaille\" ab, was wörtlich soviel wie „Muschelwerk“ bzw. \"Muschelstil\" bedeutet."}]'::jsonb, ''),
  ('eablaunde', 'Eablaunde', '', '', '', '', 'Erblande', '[{"kategorie": "", "text": "Diese Ländereien bildeten den Kern der habsburgischen Macht und umfassten weite Teile des heutigen Österreich sowie angrenzende Gebiete. Sie waren das Zentrum der Habsburgerherrschaft im [[Heiligen]] Römischen Reich und später im [[Kaisertum]] Österreich"}, {"kategorie": "", "text": "Bestandteile der österreichischen Erblande: (i) [[Herzogtum]] Österreich (das eigentliche Kernland, zu dem das heutige Niederösterreich und Oberösterreich gehörten. Wien, als Hauptstadt, war das politische und administrative Zentrum der Erblande), (ii) Steiermark, Kärnten und Krain (diese Herzogtümer wurden durch Heiraten und Erbverträge ebenfalls in die habsburgischen Erblande eingegliedert), (iii) Tirol und Vorarlberg (Tirol kam 1363 unter die Kontrolle der [[Habsburger]] und war von großer strategischer Bedeutung, da es die Alpenpässe kontrollierte), (iv) [[Vorderösterreich]] (dazu gehörten verschiedene verstreute Gebiete im heutigen Südwestdeutschland und der Schweiz, die für die habsburgische Kontrolle über den süddeutschen Raum wichtig waren), (v) Salzburg (das Erzstift Salzburg wurde erst im 19. Jahrhundert vollständig in die [[Habsburgermonarchie]] integriert, war aber ein wichtiger Teil der [[Erblande]])"}, {"kategorie": "", "text": "Die österreichischen Erblande bildeten das stabile Herrschaftszentrum der Habsburger und waren das Rückgrat ihrer Macht innerhalb des [[Heiligen]] Römischen Reiches und später des [[Kaisertums]] Österreich. Sie bildeten die Basis für den habsburgischen Einfluss, der sich weit über die Erblande hinaus auf ganz Mitteleuropa erstreckte. Die Habsburger betrachteten diese Gebiete als ihren angestammten Besitz, weshalb sie sie besonders stark verteidigten und pflegten"}, {"kategorie": "", "text": "Die [[Erblande]] wurden zentral von Wien aus regiert, und die habsburgischen [[Kaiser]] und [[Erzherzöge]] konzentrierten ihre Macht zunehmend auf diese Territorien. Die Verwaltung der Erblande war eine wesentliche Aufgabe des [[Wiener]] Hofs und des habsburgischen Beamtenapparats."}]'::jsonb, ''),
  ('heazogtum', 'Heazogtum', '', '', '', '', 'Herzogtum', '[{"kategorie": "hist.", "text": "\"Territorium oder [[Fürstentum]], das von einem Herzog oder einer Herzogin regiert wird\""}, {"kategorie": "", "text": "Im historischen Kontext Österreichs bezieht sich der Begriff auf die [[Markgrafschaft]] Österreich, die 1156 entstand, als der deutsche Kaiser [[Friedrich]] I. Barbarossa die Markgrafschaft Österreich durch das Privilegium Minus zum Herzogtum erhob. Damit wurde Österreich von Bayern unabhängig und der Babenberger [[Heinrich]] II. Jasomirgott wurde erster Herzog von Österreich"}, {"kategorie": "", "text": "Die Erhebung zum Herzogtum markierte einen entscheidenden Schritt in der Geschichte Österreichs, da es dadurch politisch aufgewertet wurde. Der Herzog von Österreich war nun ein bedeutender [[Fürst]] innerhalb des [[Heiligen]] Römischen Reiches"}, {"kategorie": "", "text": "Nach dem Aussterben der [[Babenberger]] Dynastie im Jahr 1246 gelangten die [[Habsburger]] 1278 nach der [[Schlacht]] bei Dürnkrut und Jedenspeigen in den Besitz des Herzogtums. Ab diesem Zeitpunkt wurde das [[Herzogtum]] Österreich das Zentrum der habsburgischen Macht und bildete die Basis für die spätere Ausweitung der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "1453 wurde das Herzogtum Österreich unter Kaiser [[Friedrich]] III. zum [[Erzherzogtum]] erhoben, was den besonderen Status des habsburgischen Österreichs weiter festigte."}]'::jsonb, ''),
  ('eazheazogtum', 'Eazheazogtum', '', '', '', '', 'Erzherzogtum', '[{"kategorie": "hist.", "text": "Territorium innerhalb des [[Heiligen]] Römischen Reiches, das vor allem das [[Kernland]] der [[Habsburgerdynastie]] umfasste, insbesondere die heutigen Gebiete Niederösterreich, Oberösterreich und Wien, und aufgrund des prestigeträchtigen Titels des [[Erzherzogs]] eine besondere politische Bedeutung hatte"}, {"kategorie": "", "text": "Wien, die Hauptstadt des Erzherzogtums, war das Zentrum der habsburgischen Verwaltung und Politik. Von hier aus regierten die Habsburger über ein weitreichendes Reich, das sich im Laufe der Jahrhunderte zu einer der größten Dynastien Europas entwickelte"}, {"kategorie": "", "text": "Das Erzherzogtum Österreich spielte eine zentrale Rolle in der Entwicklung der Habsburgermonarchie. Es war nicht nur das Kernland der Habsburger, sondern auch das Symbol ihrer Macht und ihres politischen Einflusses"}, {"kategorie": "", "text": "Die Einführung des [[Erzherzog-Titels]] half den Habsburgern, ihre Herrschaft im [[Heiligen]] Römischen Reich zu festigen und ihre dynastische Vormachtstellung in Europa zu sichern"}, {"kategorie": "", "text": "Das Erzherzogtum Österreich war ein entscheidendes Element der habsburgischen Machtstruktur und trug wesentlich zur Erhöhung des Status der [[Habsburger]] bei. Es markierte den Aufstieg Österreichs von einem [[Herzogtum]] zu einem dominierenden Machtzentrum im Heiligen Römischen Reich und legte den Grundstein für die spätere habsburgische Weltmacht."}]'::jsonb, ''),
  ('fueastntum', 'Füastntum', '', '', '', '', 'Fürstentum', '[{"kategorie": "hist.", "text": "\"Territorium, das von einem Fürsten oder einer Fürstin regiert wird\""}, {"kategorie": "", "text": "In der Geschichte Österreichs spielte der Begriff eine wichtige Rolle, da viele Gebiete innerhalb des [[Heiligen]] Römischen Reiches und der [[Habsburgermonarchie]] als Fürstentümer organisiert waren"}, {"kategorie": "", "text": "Fürstentümer waren in der Rangordnung der Territorien unterhalb eines [[Herzogtums]] oder [[Erzherzogtums]] angesiedelt, aber dennoch von erheblicher politischer Bedeutung"}, {"kategorie": "", "text": "In der Zeit des Heiligen Römischen Reiches gab es zahlreiche Fürstentümer, die formal dem [[Kaiser]] unterstanden, aber weitgehend selbstständig regiert wurden. Österreich selbst war nicht direkt ein Fürstentum, doch zahlreiche kleinere Fürstentümer existierten innerhalb des Reiches und spielten in der Reichspolitik eine Rolle"}, {"kategorie": "", "text": "Während der [[Habsburgermonarchie]] gab es auch einige Territorien, die den Rang eines Fürstentums hatten und von Mitgliedern des [[Hauses]] Habsburg oder von anderen [[Adelsgeschlechtern]] verwaltet wurden. Diese Gebiete waren in das größere Gefüge der Habsburgermonarchie integriert"}, {"kategorie": "", "text": "Einige Fürstentümer, wie etwa das Erzstift Salzburg, hatten sowohl weltliche als auch kirchliche Macht. Salzburg war ein geistliches Fürstentum und gleichzeitig ein eigenständiges Territorium, bevor es später in die Habsburgermonarchie eingegliedert wurde."}]'::jsonb, ''),
  ('kaisatum', 'Kaisatum', '', '', '', '', 'Kaisertum', '[{"kategorie": "allg.", "text": "\"Regierungsform, in der ein [[Kaiser]] (lat. Imperator) als Staatsoberhaupt fungiert\""}, {"kategorie": "", "text": "Ein Kaisertum kann auch den geografischen Bereich umfassen, über den ein Kaiser herrscht"}, {"kategorie": "", "text": "Ein Kaiser steht in der monarchischen Hierarchie über einem [[König]] und beansprucht oft eine universale, übernationale Macht, insbesondere in historisch bedeutenden Kaisertümern wie dem [[Heiligen]] Römischen Reich oder dem [[Kaisertum]] Österreich"}, {"kategorie": "", "text": "Der Titel \"Kaiser\" leitet sich vom lateinischen Begriff Caesar ab, der ursprünglich in der römischen Kaiserzeit als Titel für den Herrscher des Römischen Reiches verwendet wurde. Später wurde der Begriff für Herrscher verwendet, die über mehrere Völker oder große Imperien herrschten"}, {"kategorie": "", "text": "Im Kaisertum liegt die Staatsgewalt in der Regel beim Kaiser, der eine erbliche, oft absolutistische Herrschaft ausübt. In manchen Fällen wurde die kaiserliche Macht durch eine Verfassung oder ein Parlament eingeschränkt ([[konstitutionelle]] Monarchie), wie es im späteren [[Kaisertum]] Österreich der Fall war"}, {"kategorie": "", "text": "Das [[Kaisertum]] Österreich wurde 1804 von Franz II., dem letzten Kaiser des [[Heiligen]] Römischen Reiches, gegründet. Dies geschah als Reaktion auf den Aufstieg Napoleons und die Gründung des französischen Kaiserreichs. Franz II. nahm den Titel Franz I., Kaiser von Österreich, an und gründete das [[Kaisertum]] Österreich, das bis 1867 bestand, als es durch die österreichisch-ungarische [[Doppelmonarchie]] ersetzt wurde."}]'::jsonb, ''),
  ('ministapraesident', 'Ministapräsident', '', '', '', '', 'Ministerpräsident', '[{"kategorie": "hist.", "text": "\"Regierungschef der österreichischen Reichshälfte des [[Habsburgerreiches]] ([[Cisleithanien]]) während der Zeit der [[konstitutionellen]] Monarchie (1867-1918), wobei seine Rolle zentral mit der Verwaltung und Führung des Staates verbunden war\""}, {"kategorie": "", "text": "Er stand an der Spitze des [[Kabinetts]] (der Regierung) und war sowohl dem [[Kaiser]] als auch dem Parlament gegenüber verantwortlich"}, {"kategorie": "", "text": "Der Ministerpräsident wurde vom Kaiser ernannt. Formal hatte der Kaiser in der Ernennung eine große Entscheidungsfreiheit, doch in der Praxis musste der Ministerpräsident in der Regel die Unterstützung des [[Reichsrates]], insbesondere des Abgeordnetenhauses, besitzen, um regieren zu können. Der Kaiser konnte den Ministerpräsidenten auch entlassen, was ihm erhebliche Macht über die Zusammensetzung der Regierung gab"}, {"kategorie": "", "text": "Der Ministerpräsident war der Leiter des [[Kabinetts]], das aus verschiedenen Ministern bestand, die jeweils für bestimmte Ressorts (z. B. Finanzen, Inneres, Justiz) verantwortlich waren. Er koordinierte die Arbeit der Minister und war dafür verantwortlich, die Regierungsentscheidungen umzusetzen. Der Ministerpräsident führte die täglichen Regierungsangelegenheiten und trug die Hauptverantwortung für die Politik des Staates gegenüber dem Kaiser und dem Parlament"}, {"kategorie": "", "text": "Insbesondere ab dem [[Österreichisch-Ungarischen]] Ausgleich von 1867, der die Doppelmonarchie begründete, musste der Ministerpräsident die Interessen der österreichischen Reichshälfte mit jenen der ungarischen Reichshälfte in Einklang bringen. Dies machte die Regierungsgeschäfte oft schwierig, da auch Ungarn unter der Leitung eines eigenen Ministerpräsidenten stand"}, {"kategorie": "", "text": "Ein bekannter Ministerpräsident war [[Karl]] von Auersperg, der in den 1860er Jahren eine bedeutende Rolle in der Verfassungsreform spielte. Er war ein Verfechter des Liberalismus und setzte sich für eine Stärkung der konstitutionellen Ordnung ein"}, {"kategorie": "", "text": "Ein anderer einflussreicher Ministerpräsident war [[Eduard]] Taaffe, der von 1879 bis 1893 regierte. Er versuchte, durch eine moderatere Politik zwischen den verschiedenen ethnischen Gruppen und politischen Strömungen im [[Reichsrat]] zu vermitteln."}]'::jsonb, ''),
  ('zensuswoirecht', 'Zensuswoirecht', '', '', '', '', 'Zensuswahlrecht', '[{"kategorie": "hist.", "text": "\"Form des Wahlrechts, bei der das aktive und/oder passive Wahlrecht an bestimmte Kriterien wie Einkommen, Besitz oder Steuerleistung gebunden ist\""}, {"kategorie": "", "text": "Nur diejenigen Bürger, die eine festgelegte wirtschaftliche Schwelle überschreiten (z. B. ein bestimmtes Einkommen haben oder eine bestimmte Menge an Steuern zahlen), sind berechtigt, an Wahlen teilzunehmen oder sich selbst zur Wahl zu stellen"}, {"kategorie": "", "text": "Diese Form des Wahlrechts begünstigt in der Regel die wohlhabenden Klassen der Gesellschaft und schließt ärmere Bürger, insbesondere die Arbeiterklasse und ländliche Bevölkerung, von der politischen Partizipation aus"}, {"kategorie": "", "text": "In der Zeit des [[Absolutismus]] und während der frühen Phase der [[konstitutionellen]] Monarchien (wie z. B. in Österreich oder Preußen) galt das Zensuswahlrecht als Mittel, um die politische Macht in den Händen der wohlhabenderen Schichten zu halten"}, {"kategorie": "", "text": "In einigen Ländern, einschließlich Österreich, gab es ein [[Kurienwahlsystem]], das eine Variante des Zensuswahlrechts darstellte. Hierbei wurden die Wähler in verschiedene Kurien (Gruppen) eingeteilt, basierend auf Einkommen, Besitz oder gesellschaftlicher Stellung, und jede Kurie hatte eine unterschiedliche Anzahl von Abgeordneten im Parlament. Wohlhabendere Kurien hatten dadurch oft überproportionalen Einfluss auf die Gesetzgebung"}, {"kategorie": "", "text": "In Österreich wurde das Zensuswahlrecht im 19. Jahrhundert angewandt, bevor es mit der [[Wahlrechtsreform]] von 1907 durch das allgemeine männliche Wahlrecht abgelöst wurde."}]'::jsonb, ''),
  ('kuriinwoisystem', 'Kuriinwoisystem', '', '', '', '', 'Kurienwahlsystem', '[{"kategorie": "hist.", "text": "\"Wahlsystem, bei dem die Wähler in verschiedene Gruppen (Kurien) eingeteilt werden, die jeweils über unterschiedliche Wahlrechte und eine festgelegte Anzahl von Vertretern im Parlament verfügen\""}, {"kategorie": "", "text": "Die Einteilung in Kurien erfolgt in der Regel auf der Grundlage sozialer, beruflicher, oder wirtschaftlicher Merkmale, wie zum Beispiel Besitz, Einkommen oder Berufsstand"}, {"kategorie": "", "text": "Dieses System war historisch in mehreren europäischen Ländern verbreitet, darunter auch im [[Habsburgerreich]], und diente der politischen Bevorzugung bestimmter sozialer Gruppen, insbesondere der wohlhabenderen Klassen"}, {"kategorie": "", "text": "Im klassischen Kurienwahlsystem waren oft folgende Gruppen (Kurien) vertreten: (i) Großgrundbesitzer (Landbesitzer oder [[Adelige]]),  (ii) Städte und Bürgertum (Handel und Gewerbe),  (iii) Industrie und Gewerbe (Wirtschaftsunternehmen),  (iv) ländliche Bevölkerung und Bauern"}, {"kategorie": "", "text": "Im Kurienwahlsystem hatte jede Kurie eine bestimmte Anzahl von Sitzen im Parlament. Oft waren wohlhabendere Kurien (wie die Großgrundbesitzer und das Bürgertum) überproportional stark vertreten, während Kurien der weniger wohlhabenden Bevölkerungsschichten, wie Bauern oder Arbeiter, eine geringere Vertretung erhielten. Diese ungleiche Gewichtung der Stimmen sorgte dafür, dass bestimmte soziale Gruppen, insbesondere die Eliten, mehr politischen Einfluss hatten als andere"}, {"kategorie": "", "text": "Im [[Habsburgerreich]] wurde das Kurienwahlsystem ab Mitte des 19. Jahrhunderts angewandt, endete dann aber schließlich mit der [[Wahlrechtsreform]] von 1907, die das allgemeine männliche Wahlrecht einführte. Damit wurde die ungleiche Gewichtung der Stimmen nach Besitz oder Einkommen beseitigt, und jeder wahlberechtigte Mann erhielt eine Stimme, unabhängig von seiner sozialen oder wirtschaftlichen Stellung. Frauen blieben vom Wahlrecht aber weiterhin ausgeschlossen."}]'::jsonb, ''),
  ('fraunwoirecht', 'Fraunwoirecht', '', '', '', '', 'Frauenwahlrecht', '[{"kategorie": "hist.", "text": "\"Recht von Frauen, aktiv und passiv an Wahlen teilzunehmen, also sowohl wählen zu dürfen als auch sich selbst zur Wahl aufstellen zu lassen\""}, {"kategorie": "", "text": "In Österreich wurde das Frauenwahlrecht im Zuge der politischen Umwälzungen nach dem [[Ersten]] Weltkrieg eingeführt, als das [[Habsburgerreich]] zerfiel und die [[Erste]] Republik Österreich gegründet wurde"}, {"kategorie": "", "text": "Am 12. November 1918, dem Tag, an dem die [[Republik]] Österreich ausgerufen wurde, wurde auch das allgemeine, gleiche Wahlrecht für Männer und Frauen verkündet. Damit erhielten Frauen in Österreich das aktive und passive Wahlrecht auf nationaler Ebene, was bedeutete, dass sie sowohl wählen als auch für politische Ämter kandidieren durften"}, {"kategorie": "", "text": "Die ersten Wahlen, an denen Frauen in Österreich teilnehmen konnten, waren die Wahlen zur [[konstituierenden]] Nationalversammlung im Februar 1919. Dies war eine historische Wahl, bei der Frauen erstmals in großem Umfang an nationalen Wahlen teilnahmen und auch als Abgeordnete gewählt werden konnten"}, {"kategorie": "", "text": "Nach der Einführung des Frauenwahlrechts 1918 war es ein fester Bestandteil des politischen Systems in der Ersten Republik und wurde auch nach dem [[Zweiten]] Weltkrieg in der [[Zweiten]] Republik beibehalten"}, {"kategorie": "", "text": "Trotz der formalen Gleichberechtigung dauerte es jedoch Jahrzehnte, bis Frauen in Österreich eine gleichberechtigte politische Vertretung in den höchsten politischen Ämtern erlangten. Der Kampf um die tatsächliche Gleichstellung in der Politik setzte sich auch nach der Einführung des Wahlrechts fort."}]'::jsonb, ''),
  ('laundesvafossung', 'Laundesvafossung', '', '', '', '', 'Landesverfassung', '[{"kategorie": "pol.", "text": "\"grundlegendes rechtliches Dokument eines österreichischen [[Bundeslandes]], das die Organisation und Funktionsweise der [[Landesregierung]] und der [[Landesverwaltung]] regelt\""}, {"kategorie": "", "text": "Sie legt die Rechte und Pflichten der Bürger im Bundesland fest, bestimmt die Zuständigkeiten der Landesorgane (wie [[Landtag]] und [[Landesregierung]]) und definiert den rechtlichen Rahmen für die Gesetzgebung und Verwaltung des Landes"}, {"kategorie": "", "text": "In Österreich sind die neun Bundesländer (z. B. Wien, Niederösterreich, Tirol) Teil eines föderalen Systems, in dem sie eine gewisse Autonomie innerhalb des Staates haben. Diese Autonomie ist in den jeweiligen Landesverfassungen verankert"}, {"kategorie": "", "text": "Die Landesverfassungen stehen in Einklang mit der [[Bundesverfassung]] und dürfen nicht im Widerspruch zu dieser stehen. Sie müssen also die Grundsätze der österreichischen Bundesverfassung, wie die [[parlamentarische]] Demokratie und den [[Rechtsstaat]], respektieren"}, {"kategorie": "", "text": "Auch in den Landesverfassungen sind [[Bürgerrechte]] und [[Grundrechte]] festgeschrieben, die den Bürgern des Bundeslandes bestimmte Freiheiten und Rechte garantieren. Diese dürfen nicht im Widerspruch zu den in der Bundesverfassung festgelegten Grundrechten stehen."}]'::jsonb, ''),
  ('foederalismus', 'Föderalismus', '', '', '', '', 'Föderalismus', '[{"kategorie": "pol.", "text": "\"politisches System, in dem die Macht und Zuständigkeiten zwischen der zentralen Regierung ([[Bund]]) und den neun [[Bundesländern]] aufgeteilt sind\""}, {"kategorie": "", "text": "Die [[Bundesverfassung]] teilt die Zuständigkeiten zwischen dem [[Bund]] und den [[Ländern]] auf. Der Bund ist für übergeordnete Aufgaben wie Außenpolitik, Verteidigung oder Finanzen zuständig, während die Länder für Bereiche wie Bildung, Raumplanung, Gesundheitswesen oder Landespolizei eigene Gesetze erlassen und diese umsetzen können"}, {"kategorie": "", "text": "Jedes der neun [[Bundesländer]] (z. B. Wien, Niederösterreich, Tirol) hat eine eigene [[Landesverfassung]], die den rechtlichen Rahmen für die Landespolitik festlegt. Die [[Landtage]] sind die gesetzgebenden Organe der Bundesländer und werden direkt von den Bürgern des jeweiligen Landes gewählt. Sie verabschieden Gesetze, die für das jeweilige Bundesland gelten, allerdings nur in den Bereichen, die in die Zuständigkeit der Länder fallen"}, {"kategorie": "", "text": "Im [[Bundesrat]], der zweiten Kammer des österreichischen Parlaments, sind die [[Bundesländer]] auf Bundesebene vertreten. Der Bundesrat kann bei Gesetzesvorhaben des [[Nationalrates]] mitwirken, insbesondere wenn die Gesetze die Kompetenzen der Länder betreffen. Der Bundesrat kann Gesetzesvorschläge des Nationalrats verzögern oder ablehnen, allerdings hat er im Vergleich zum Nationalrat weniger Einfluss"}, {"kategorie": "", "text": "Die Finanzierung der Aufgaben von [[Bund]] und Ländern ist ein zentraler Aspekt des Föderalismus. In Österreich wird ein großer Teil der Steuereinnahmen zentral durch den Bund erhoben und dann im Rahmen des [[Finanzausgleichs]] an die Länder verteilt. Dadurch werden finanzielle Ungleichheiten zwischen den wohlhabenderen und den wirtschaftlich schwächeren Ländern ausgeglichen"}, {"kategorie": "", "text": "Österreich praktiziert einen [[kooperativen]] Föderalismus, was bedeutet, dass Bund und Länder eng zusammenarbeiten müssen, um nationale Ziele zu erreichen. Viele politische und gesetzgeberische Entscheidungen erfordern daher die Abstimmung zwischen den verschiedenen Ebenen."}]'::jsonb, 'Da Bund'),
  ('finanzausgleich', 'Finanzausgleich', '', '', '', '', 'Finanzausgleich', '[{"kategorie": "pol.", "text": "\"Mechanismus in föderalen Staaten wie Österreich, der die finanzielle Verteilung von Steuereinnahmen zwischen dem [[Bund]], den [[Bundesländern]] und den Gemeinden regelt\""}, {"kategorie": "", "text": "Ziel des Finanzausgleichs ist es, finanzielle Ungleichheiten zwischen wohlhabenderen und weniger wohlhabenden Regionen auszugleichen und allen staatlichen Ebenen ausreichend Mittel zur Erfüllung ihrer Aufgaben zur Verfügung zu stellen"}, {"kategorie": "", "text": "Der Großteil der Steuern, wie etwa die Einkommensteuer, Körperschaftsteuer oder Mehrwertsteuer, wird vom Bund eingehoben. Diese Einnahmen werden anschließend nach festgelegten Schlüsseln auf Bund, Länder und Gemeinden aufgeteilt"}, {"kategorie": "", "text": "Der Finanzausgleich wird regelmäßig neu ausgehandelt. In Österreich geschieht dies üblicherweise alle vier bis fünf Jahre in Verhandlungen zwischen dem Bund und den Ländern. In diesem Prozess werden neue Verteilungsschlüssel festgelegt und Anpassungen an veränderte wirtschaftliche Rahmenbedingungen vorgenommen"}, {"kategorie": "", "text": "Der Finanzausgleich ist entscheidend für die finanzielle Autonomie der Länder und Gemeinden. Da sie selbst nur begrenzte Steuereinnahmen direkt einheben, sind sie auf die Mittel aus dem Finanzausgleich angewiesen, um ihre Aufgaben in Bereichen wie Bildung, Gesundheitswesen, Infrastruktur oder Soziales zu finanzieren"}, {"kategorie": "", "text": "Der Finanzausgleich spiegelt das Prinzip des [[kooperativen]] Föderalismus wider, da Bund und Länder eng zusammenarbeiten müssen, um eine gerechte Verteilung der finanziellen Mittel sicherzustellen."}]'::jsonb, ''),
  ('schdoodsgwoid', 'Schdoodsgwoid', '', '', '', '', 'Staatsgewalt', '[{"kategorie": "pol.", "text": "\"die Macht und Autorität, die ein Staat ausübt, um seine Gesetze und Regelungen durchzusetzen, das öffentliche Leben zu organisieren und die Rechte seiner Bürger zu schützen\""}, {"kategorie": "", "text": "In modernen Staaten ist die Staatsgewalt in drei Gewalten unterteilt, um die Macht zu kontrollieren und auszugleichen: (i) [[Legislative]] (gesetzgebende Gewalt), (ii) [[Exekutive]] (ausführende Gewalt) und (iii) [[Judikative]] (rechtsprechende Gewalt)"}, {"kategorie": "", "text": "Der Staat hat das Monopol, legitime Gewalt auszuüben, um Ordnung und Sicherheit zu gewährleisten. Dies schließt den Einsatz von Zwangsmitteln durch Polizei und andere Behörden ein, um Gesetze durchzusetzen oder Straftaten zu verhindern"}, {"kategorie": "", "text": "Die Staatsgewalt ist ein Ausdruck der Souveränität eines Staates, das heißt, sie wird unabhängig von anderen Staaten oder externen Mächten ausgeübt. Diese Souveränität ermöglicht es dem Staat, eigenständig über seine inneren Angelegenheiten zu entscheiden"}, {"kategorie": "", "text": "Die Ausübung der Staatsgewalt muss immer im Einklang mit den Rechten und Freiheiten der Bürger stehen. Die Verfassung regelt, in welchen Bereichen der Staat seine Macht ausüben darf, und schützt die Bürger vor einem Übermaß an staatlicher Kontrolle."}]'::jsonb, ''),
  ('legislative', 'Legislative', '', '', '', '', 'Legislative', '[{"kategorie": "pol.", "text": "\"gesetzgebende Gewalt eines Staates und einer der drei zentralen Bereiche der [[Gewaltenteilung]], neben der [[Exekutive]] (ausführende Gewalt) und der [[Judikative]] (rechtsprechende Gewalt)\""}, {"kategorie": "", "text": "Die Legislative ist für die Erstellung und Verabschiedung von Gesetzen zuständig. Sie legt fest, welche Regeln und Vorschriften für alle Bürger des Staates gelten. In Österreich ist dies Aufgabe des [[Parlaments]], das aus dem [[Nationalrat]] und dem [[Bundesrat]] besteht"}, {"kategorie": "", "text": "Neben der Gesetzgebung überwacht die Legislative die [[Exekutive]] (Regierung und Verwaltung). Sie kontrolliert, ob die Exekutive die Gesetze richtig umsetzt, und kann bei Missständen eingreifen. In parlamentarischen Systemen wie in Österreich kann das Parlament die Regierung durch [[Misstrauensvoten]] zur Rechenschaft ziehen."}]'::jsonb, ''),
  ('exekutive', 'Exekutive', '', '', '', '', 'Exekutive', '[{"kategorie": "pol.", "text": "\"die ausführende Gewalt im Staat, welche für die Durchführung und Umsetzung der Gesetze verantwortlich ist, die von der [[Legislative]] (dem Parlament) beschlossen werden\""}, {"kategorie": "", "text": "Sie ist Teil des [[Gewaltenteilungsprinzips]], welches die drei Gewalten Legislative, Exekutive und [[Judikative]] klar voneinander trennt, um Machtmissbrauch zu verhindern"}, {"kategorie": "", "text": "Die Exekutive in Österreich wird von der [[Bundesregierung]] und den [[Landesregierungen]] gebildet"}, {"kategorie": "", "text": "Auf Bundesebene besteht sie aus dem [[Bundespräsidenten]], der als Staatsoberhaupt eine repräsentative und formell übergeordnete Rolle spielt, sowie der [[Bundesregierung]], bestehend aus dem [[Bundeskanzler]], dem [[Vizekanzler]] und den [[Bundesministern]]. Der Bundeskanzler leitet die Regierungsgeschäfte, während die Minister für ihre jeweiligen Ressorts verantwortlich sind. Die Bundesregierung ist verantwortlich für die Außenpolitik, die Verteidigung, die innere Sicherheit und die Verwaltung auf Bundesebene"}, {"kategorie": "", "text": "Auf Länderebene besteht die Exekutive aus den [[Landeshauptleuten]] und den [[Landesregierungen]], die für die Verwaltung und Gesetzesvollziehung in den einzelnen Bundesländern zuständig sind"}, {"kategorie": "", "text": "Zusätzlich zur Regierung ist die Exekutive auch für die Polizei und andere Sicherheitsbehörden verantwortlich, die dafür sorgen, dass Gesetze eingehalten und Ordnung aufrechterhalten wird. Ein weiteres wichtiges Element der Exekutive ist die öffentliche Verwaltung, die die alltäglichen Regierungsaufgaben wie das Erheben von Steuern oder die Ausstellung von Dokumenten wie Pässen und Führerscheinen übernimmt"}, {"kategorie": "", "text": "Die Exekutive handelt immer im Rahmen der geltenden Gesetze und unterliegt der Kontrolle durch die [[Judikative]] (Gerichte), um sicherzustellen, dass ihre Handlungen rechtskonform sind​."}]'::jsonb, ''),
  ('praesidiale', 'Präsidiale', '', '', '', '', 'Präsidiale', '[{"kategorie": "pol.", "text": "\"zentrales Gremium der [[Präsidialkonferenz]], das für die Koordination und Organisation der parlamentarischen Arbeit im [[Nationalrat]] verantwortlich ist\""}, {"kategorie": "", "text": "Die Präsidiale besteht aus den drei [[Nationalratspräsidenten]] sowie Vertretern aller im Nationalrat vertretenen [[Fraktionen]] und erfüllt wesentliche administrative und organisatorische Aufgaben, die den reibungslosen Ablauf der parlamentarischen Sitzungen und die effiziente Arbeit des Parlaments sichern sollen"}, {"kategorie": "", "text": "Die wichtigsten Aufgaben der Präsidiale umfassen:  (i) Sitzungsplanung: Die Präsidiale legt die Tagesordnung für die [[Nationalratssitzungen]] fest und stimmt sich dabei mit den Fraktionen über die Reihenfolge der Beratungen ab;  (ii) Zeitliche und inhaltliche Koordination: Sie steuert den Ablauf der Debatten, regelt Redezeiten und plant die Abfolge der parlamentarischen Arbeit;  (iii) Zuweisung von [[Ausschüssen]]: Die Präsidiale entscheidet, welche Themen an welche parlamentarischen Ausschüsse überwiesen werden, sodass eine sachgerechte Beratung der Themen stattfinden kann;  (iv) Hausrecht und Ordnung im Plenarsaal: Die Präsidenten, die Teil der Präsidiale sind, wahren das Hausrecht und sorgen für die Einhaltung der Regeln im [[Plenarsaal]]"}, {"kategorie": "", "text": "Durch die Präsidiale können die Interessen der verschiedenen Fraktionen im Nationalrat bei organisatorischen Entscheidungen berücksichtigt werden, was zu einer ausgewogenen Planung und Durchführung der Parlamentsarbeit beiträgt"}, {"kategorie": "", "text": "Die Struktur und Arbeitsweise der Präsidiale spiegelt somit den parlamentarischen Charakter des österreichischen Systems wider und fördert eine effektive, kooperative und transparente parlamentarische Zusammenarbeit."}]'::jsonb, ''),
  ('praesidialsitzung', 'Präsidialsitzung', '', '', '', '', 'Präsidialsitzung', '[{"kategorie": "pol.", "text": "\"Zusammenkunft der [[Präsidiale]], das heißt jenes Gremiums, das die Sitzungen und organisatorischen Abläufe des [[Nationalrats]] koordiniert\""}, {"kategorie": "", "text": "Die Präsidialsitzung dient dazu, wichtige Entscheidungen über den Ablauf der parlamentarischen Arbeit zu treffen"}, {"kategorie": "", "text": "In einer Präsidialsitzung kommen der Präsident des Nationalrats ([[Nationalratspräsident]]), die zwei Vizepräsidenten sowie die [[Fraktionsvorsitzenden]] aller im Nationalrat vertretenen Parteien zusammen, um verschiedene organisatorische Punkte zu besprechen und zu entscheiden"}, {"kategorie": "", "text": "Wichtige Aufgaben und Themen, die in Präsidialsitzungen behandelt werden, sind:  (i) Festlegung der Tagesordnung für die nächsten [[Plenarsitzungen]]: Hier werden Themen und Gesetzesvorschläge, die zur Diskussion und Abstimmung anstehen, zeitlich und inhaltlich geordnet;  (ii) Zuteilung der Redezeiten: Die Präsidialsitzung bestimmt die Rederechte und -zeiten der Abgeordneten und Fraktionen, um eine geordnete Debatte zu gewährleisten;  (iii) Organisatorische und interne Angelegenheiten: Die Sitzung befasst sich mit organisatorischen Abläufen, wie der Verteilung von Räumen, Terminen und anderen technischen Abläufen, die den Parlamentsbetrieb betreffen;  (iv) Koordinierung zwischen den [[Fraktionen]]: Die Präsidialsitzung fördert den Austausch zwischen den Fraktionen, insbesondere bei strittigen Themen, und versucht, im Vorfeld von Plenarsitzungen Konsens oder Kompromisse zu finden"}, {"kategorie": "", "text": "Durch die regelmäßigen Präsidialsitzungen wird die Arbeit des [[Nationalrats]] effizient organisiert und strukturiert, wodurch eine effektive und geregelte parlamentarische Debatte ermöglicht wird."}]'::jsonb, ''),
  ('fraktion', 'Fraktion', '', '', '', '', 'Fraktion', '[{"kategorie": "pol.", "text": "\"organisierte Gruppe von Abgeordneten im [[Parlament]], die derselben politischen Partei oder einem gemeinsamen politischen Ziel angehören\""}, {"kategorie": "", "text": "Im österreichischen [[Nationalrat]] bilden beispielsweise die Abgeordneten, die für dieselbe Partei gewählt wurden, eine Fraktion"}, {"kategorie": "", "text": "Die Fraktionen sind zentrale Einheiten der politischen Arbeit im Parlament und vertreten geschlossen die Interessen und Positionen ihrer Partei"}, {"kategorie": "", "text": "Wichtige Merkmale und Aufgaben einer Fraktion sind:  (i) Vertretung politischer Positionen: Fraktionen bündeln die Standpunkte und Interessen ihrer Mitglieder, sodass diese als Einheit auftreten und eine gemeinsame Linie verfolgen können;  (ii) Organisation und Koordination der Parlamentsarbeit: Fraktionen bereiten [[parlamentarische]] Initiativen vor, wie z. B. [[Gesetzesvorschläge]] und Anträge, und stimmen ihre Mitglieder auf Abstimmungen ein;  (iii) Stärkung der Durchsetzungskraft: Durch den Zusammenschluss in Fraktionen gewinnen die einzelnen Abgeordneten an Einfluss, da die Fraktion als geschlossenes Gremium mit mehr Gewicht im Parlament auftreten kann;  (iv) Bereitstellung von Ressourcen und Unterstützung: Fraktionen bieten ihren Mitgliedern organisatorische und personelle Unterstützung, z. B. durch Fachreferenten, um die Parlamentsarbeit effizienter zu gestalten;  (v) Verhandlungen und Kompromisse: Fraktionen führen Verhandlungen mit anderen Fraktionen, um politische Kompromisse zu finden oder Mehrheiten für Gesetzesvorhaben zu bilden"}, {"kategorie": "", "text": "In der Regel erhält jede Fraktion im Parlament eine bestimmte Anzahl an Redezeiten und Sitzen in [[Ausschüssen]], die nach der Stärke der jeweiligen Fraktion bemessen wird. Damit spielen Fraktionen eine entscheidende Rolle für die Strukturierung und den Ablauf der parlamentarischen Arbeit und ermöglichen es, die politischen Ziele ihrer Mitglieder wirkungsvoll zu vertreten."}]'::jsonb, ''),
  ('fraktionsvoasitzenda', 'Fraktionsvoasitzenda', '', '', '', '', 'Fraktionsvorsitzender', '[{"kategorie": "pol.", "text": "\"gewählter Leiter einer [[Fraktion]] (Abgeordnetengruppe) innerhalb des Parlaments\""}, {"kategorie": "", "text": "In Österreich, etwa im [[Nationalrat]], ist der Fraktionsvorsitzende für die Organisation und Vertretung seiner Fraktion verantwortlich"}, {"kategorie": "", "text": "Die Fraktion umfasst alle Abgeordneten, die einer bestimmten politischen [[Partei]] angehören, und bildet eine organisatorische Einheit im Parlament"}, {"kategorie": "", "text": "Zu den Hauptaufgaben eines Fraktionsvorsitzenden gehören:  (i) Vertretung der Fraktion: Er oder sie vertritt die Interessen und Positionen der Fraktion nach außen, sowohl gegenüber anderen Fraktionen als auch gegenüber der Parlamentsleitung und der Öffentlichkeit;  (ii) Koordination der Fraktionsarbeit: Der Fraktionsvorsitzende organisiert und koordiniert die politische Arbeit innerhalb der Fraktion, einschließlich der Vorbereitung auf [[Plenarsitzungen]], [[Ausschüsse]] und Abstimmungen;  (iii) Festlegung der Fraktionslinie: Gemeinsam mit anderen führenden Mitgliedern der Fraktion entwickelt der Vorsitzende die politische Ausrichtung und Positionen zu aktuellen Themen und [[Gesetzesvorschlägen]], die dann geschlossen vertreten werden;  (iv) Kommunikation und Verhandlungen: Der Fraktionsvorsitzende verhandelt mit anderen Fraktionen und politischen Akteuren, um politische Kompromisse oder Allianzen zu schmieden;  (v) Ansprechpartner für die Fraktionsmitglieder: Er oder sie ist der Ansprechpartner für die Abgeordneten der Fraktion und unterstützt diese bei ihrer parlamentarischen Arbeit"}, {"kategorie": "", "text": "Insgesamt spielt der Fraktionsvorsitzende eine zentrale Rolle in der strategischen Ausrichtung und effektiven Organisation der politischen Arbeit einer Partei innerhalb des Parlaments."}]'::jsonb, ''),
  ('bundesfinaunzgericht', 'Bundesfinaunzgericht', '', '', '', '', 'Bundesfinanzgericht', '[{"kategorie": "allg.", "text": "\"Gericht in Österreich, das in erster Instanz über finanzrechtliche Streitigkeiten entscheidet\""}, {"kategorie": "", "text": "Es wurde 2014 gegründet und löste in diesem Bereich die Unabhängigen Finanzsenate ab"}, {"kategorie": "", "text": "Das Bundesfinanzgericht ist Teil der Verwaltungsgerichtsbarkeit und ist speziell für Verfahren zuständig, die Steuerangelegenheiten, Abgaben und Zölle betreffen"}, {"kategorie": "", "text": "Hauptaufgaben und Funktionen des Bundesfinanzgerichts:  (i) \nEntscheidung über Steuer- und Abgabenstreitigkeiten: Das BFG entscheidet in erster Instanz über [[Rechtsmittel]], die gegen Entscheidungen der [[Finanzbehörden]] eingebracht werden. Dazu gehören Streitfälle zu Einkommens-, Körperschafts-, Umsatzsteuer und anderen Abgaben;  (ii) Verfahren zu Zoll- und Finanzstrafrecht: Das Gericht ist auch für Fälle zuständig, die das Zollrecht sowie Finanzstrafen betreffen, etwa bei Verstößen gegen steuerrechtliche Bestimmungen;  (iii) Sicherung der [[Rechtsstaatlichkeit]] im Finanzbereich: Das BFG gewährleistet durch unabhängige Entscheidungen die Einhaltung der Gesetze im Finanzwesen und schützt die Bürger vor unrechtmäßigen Verwaltungsakten;  (iv) Instanz für Beschwerden gegen Finanzverwaltungsentscheidungen: Bürger, Unternehmen oder andere Rechtsträger können gegen Entscheidungen der Finanzämter und Zollbehörden Beschwerde beim Bundesfinanzgericht einlegen;  (v) Zusammenarbeit mit dem [[Verwaltungsgerichtshof]] (VwGH): Gegen Urteile des BFG kann unter bestimmten Voraussetzungen [[Revision]] beim Verwaltungsgerichtshof eingelegt werden, wenn es sich um Grundsatzfragen handelt"}, {"kategorie": "", "text": "Das Bundesfinanzgericht hat seinen Hauptsitz in Wien und verfügt über mehrere Außenstellen in Österreich. Es ist ein wesentliches Instrument zur Durchsetzung des Steuerrechts und trägt zur Transparenz und Rechtssicherheit in finanzrechtlichen Fragen bei."}]'::jsonb, ''),
  ('finanzbehoeadn', 'Finanzbehöadn', '', '', '', '', 'Finanzbehörden', '[{"kategorie": "allg.", "text": "\"staatliche Institutionen, die für die Verwaltung, Erhebung und Kontrolle von Steuern und Abgaben zuständig sind\""}, {"kategorie": "", "text": "In Österreich umfassen die Finanzbehörden verschiedene Einrichtungen, die jeweils spezielle Aufgaben im Bereich des Steuerwesens und der Finanzverwaltung erfüllen. Ihre Hauptaufgabe ist die Sicherstellung der ordnungsgemäßen Besteuerung und damit die Bereitstellung von Mitteln zur Finanzierung staatlicher Aufgaben"}, {"kategorie": "", "text": "Struktur der Finanzbehörden in Österreich:  (i) Die oberste Finanzbehörde ist das Bundesministerium für Finanzen (BMF), das für die steuer- und abgabenrechtliche Gesetzgebung und die übergeordnete Leitung der Finanzverwaltung verantwortlich ist;  (ii) Ihm untergeordnet sind Finanzämter und Zollämter, die jeweils für verschiedene Regionen und spezifische Steuerarten oder Zollangelegenheiten zuständig sind;  (iii) Auch das Finanzamt Österreich und das Zollamt Österreich zählen zu diesen Behörden und nehmen länderübergreifende Aufgaben wahr"}, {"kategorie": "", "text": "Insgesamt sorgen die Finanzbehörden durch die Verwaltung und Einhebung öffentlicher Abgaben dafür, dass der Staat seinen finanziellen Verpflichtungen nachkommt und öffentliche Dienstleistungen finanzieren kann."}]'::jsonb, ''),
  ('finanzpolizei', 'Finanzpolizei', '', '', '', '', 'Finanzpolizei', '[{"kategorie": "allg.", "text": "\"spezialisierte Behörde innerhalb der österreichischen [[Finanzverwaltung]], die insbesondere zur Bekämpfung von Finanzdelikten und zur Durchsetzung steuerrechtlicher und arbeitsrechtlicher Vorschriften eingesetzt wir\""}, {"kategorie": "", "text": "Sie wurde 2011 als Teil der Steuer- und Abgabensicherung gegründet und ist dem Bundesministerium für Finanzen (BMF) unterstellt"}, {"kategorie": "", "text": "Wichtige Aufgaben und Funktionen der Finanzpolizei:  (i) Bekämpfung von Schwarzarbeit und Sozialbetrug: Die Finanzpolizei kontrolliert Unternehmen und Privatpersonen, um illegale Beschäftigung, Schwarzarbeit und Verstöße gegen sozialversicherungsrechtliche Verpflichtungen aufzudecken;  (ii) Überprüfung von steuerrechtlichen Verstößen: Sie ermittelt in Fällen von Steuerhinterziehung, etwa bei nicht deklarierten Einnahmen oder bei Missbrauch von Sozialleistungen;  (iii) Kontrolle im Bereich der Abgabenordnung: Die Finanzpolizei überprüft die ordnungsgemäße Einhaltung von steuer- und abgabenrechtlichen Vorschriften in Unternehmen, wie die korrekte Versteuerung von Umsätzen und die Zahlung von Abgaben;  (iv) Überwachung der Einhaltung von arbeitsrechtlichen Vorschriften: Dazu gehören etwa die Kontrolle der Mindestlohnbestimmungen und Arbeitszeiten sowie die Prüfung, ob Beschäftigte korrekt gemeldet und sozialversichert sind;  (v) Zusammenarbeit mit anderen Behörden: Die Finanzpolizei arbeitet eng mit anderen Strafverfolgungsbehörden wie der [[Polizei]], der [[Zollbehörde]] und der [[Justiz]] zusammen, um komplexe Fälle zu lösen und die Durchsetzung der Gesetze zu stärken;  (vi) Sicherstellung von illegalen Waren: Im Rahmen ihrer Ermittlungen kann die Finanzpolizei Waren beschlagnahmen, die illegal eingeführt oder verkauft wurden, wie beispielsweise gefälschte Produkte oder nicht versteuerte Waren"}, {"kategorie": "", "text": "Die Finanzpolizei hat weitreichende Kontrollbefugnisse, die ihr ermöglichen, unangekündigte Betriebsprüfungen durchzuführen, Geschäftsräume zu betreten und Einsicht in Geschäftsunterlagen zu nehmen. Sie kann Verstöße unmittelbar ahnden und Strafen verhängen oder Strafverfahren einleiten"}, {"kategorie": "", "text": "Insgesamt leistet die Finanzpolizei einen wesentlichen Beitrag zur Bekämpfung von Finanzkriminalität und zum Schutz der legalen Wirtschaft in Österreich, indem sie für eine gerechte Verteilung der Steuerlast und die Einhaltung gesetzlicher Bestimmungen sorgt."}]'::jsonb, ''),
  ('bundesvawoitungsgericht', 'Bundesvawoitungsgericht', '', '', '', '', 'Bundesverwaltungsgericht', '[{"kategorie": "allg.", "text": "\"Gericht in Österreich, das als zentrale Instanz für die Überprüfung von Verwaltungsentscheidungen zuständig ist\""}, {"kategorie": "", "text": "Es wurde 2014 im Zuge der Verwaltungsgerichtsbarkeits-Novelle gegründet und bildet seither eine wichtige Säule der Verwaltungsgerichtsbarkeit. Ziel ist es, Bürgern die Möglichkeit zu geben, behördliche Entscheidungen auf ihre Rechtmäßigkeit überprüfen zu lassen"}, {"kategorie": "", "text": "Hauptaufgaben und Zuständigkeiten des Bundesverwaltungsgerichts:  (i) Überprüfung von Verwaltungsentscheidungen: Das BVwG entscheidet in erster Instanz über Beschwerden gegen Bescheide von [[Verwaltungsbehörden]] des Bundes. Dazu zählen Entscheidungen in Bereichen wie Asyl, Fremdenrecht, Sozialversicherung und Beamtenrecht;  (ii) Sicherung der [[Rechtsstaatlichkeit]]: Durch die unabhängige Überprüfung der Verwaltungsakte gewährleistet das Gericht, dass behördliche Entscheidungen rechtskonform und verhältnismäßig sind, und schützt so die Rechte der Bürger;  (iii) Entscheidung über [[Maßnahmenbeschwerden]]: Das BVwG behandelt Beschwerden gegen Zwangsmaßnahmen oder behördliche Eingriffe, wie Durchsuchungen oder [[Zwangsvollstreckungen]], die durch Bundesbehörden veranlasst wurden;  (iv) Schutz der [[Grundrechte]]: Im Rahmen der Verwaltungsgerichtsbarkeit prüft das Gericht, ob die Entscheidungen der Behörden die verfassungsrechtlich garantierten Grundrechte der Betroffenen einhalten;  (v) Verwaltungsdisziplinarrecht und Berufsrecht: Das BVwG ist zuständig für Entscheidungen in Disziplinarverfahren gegen Beamte und Entscheidungen im Berufsrecht für einige Berufsgruppen wie Ärzte oder Rechtsanwälte"}, {"kategorie": "", "text": "Das BVwG hat seinen Hauptsitz in Wien, arbeitet jedoch österreichweit und ist in mehrere Senate gegliedert, die auf spezifische Fachgebiete spezialisiert sind. Das BVwG steht in einer hierarchischen Struktur, in der seine Entscheidungen unter bestimmten Bedingungen beim [[Verwaltungsgerichtshof]] (VwGH) oder beim [[Verfassungsgerichtshof]] (VfGH) angefochten werden können."}]'::jsonb, ''),
  ('moossnaumenbeschweade', 'Moossnaumenbeschweade', '', '', '', '', 'Maßnahmenbeschwerde', '[{"kategorie": "jur.", "text": "\"[[Rechtsmittel]] in Österreich, das es Bürgern ermöglicht, sich gegen unmittelbare Zwangsakte oder Maßnahmen von [[Verwaltungsbehörden]] oder deren Organen zur Wehr zu setzen, wenn sie dadurch in ihren Rechten verletzt wurden\""}, {"kategorie": "", "text": "Die Maßnahmenbeschwerde ist Teil des Rechtsschutzsystems und dient dazu, die [[Grundrechte]] gegenüber behördlichen Eingriffen zu wahren"}, {"kategorie": "", "text": "Merkmale und Voraussetzungen der Maßnahmenbeschwerde:  (i) Anwendungsbereich: Eine Maßnahmenbeschwerde kann bei unmittelbaren Eingriffen durch Organe der Verwaltungsbehörden eingebracht werden, wenn diese Maßnahmen keine formellen [[Bescheide]] sind, aber dennoch Rechtswirkungen entfalten. Beispiele sind Durchsuchungen, Festnahmen oder Platzverweise;  (ii) Rechtsverletzung: Die betroffene Person muss darlegen, dass durch die Maßnahme ein subjektives Recht, wie etwa das Recht auf persönliche Freiheit oder Eigentum, verletzt wurde;  (iii) Zuständiges Gericht: Maßnahmenbeschwerden gegen Organe des Bundes werden beim [[Bundesverwaltungsgericht]] (BVwG) eingebracht. Für Maßnahmen der Landesbehörden oder Gemeindebehörden sind die jeweiligen [[Landesverwaltungsgerichte]] zuständig;  (iv) Frist: Die Beschwerde muss grundsätzlich innerhalb von sechs Wochen ab dem Zeitpunkt der Kenntnis der Maßnahme eingebracht werden;  (v) Prüfung und Entscheidung: Das zuständige Gericht prüft die Rechtmäßigkeit und Verhältnismäßigkeit der Maßnahme und entscheidet, ob der Eingriff rechtswidrig war. Bei Feststellung einer Rechtswidrigkeit kann das Gericht den Behörden Auflagen für die Zukunft erteilen und gegebenenfalls eine Entschädigung anordnen."}]'::jsonb, ''),
  ('laundesvawoitungsgericht', 'Laundesvawoitungsgericht', '', '', '', '', 'Landesverwaltungsgericht', '[{"kategorie": "jur.", "text": "\"Verwaltungsgericht in Österreich, das auf Landesebene angesiedelt ist und für die Überprüfung von Verwaltungsentscheidungen zuständig ist, die durch Behörden der jeweiligen Bundesländer getroffen wurden\""}, {"kategorie": "", "text": "Die Landesverwaltungsgerichte wurden im Zuge der Verwaltungsgerichtsbarkeits-Novelle 2014 eingerichtet und dienen als erste Instanz in Verwaltungsangelegenheiten, um den Rechtsschutz der Bürger auf Landesebene zu gewährleisten"}, {"kategorie": "", "text": "Hauptaufgaben und Zuständigkeiten der Landesverwaltungsgerichte:  (i) Überprüfung von Landesverwaltungsakten: Das LVwG entscheidet über Beschwerden gegen Bescheide und sonstige Verwaltungsakte der Landesbehörden. Es prüft diese auf ihre Rechtmäßigkeit und stellt sicher, dass die Rechte der Bürger gewahrt bleiben;  (ii) Entscheidung über [[Maßnahmenbeschwerden]]: Das LVwG ist zuständig für Maßnahmenbeschwerden, die sich gegen unmittelbare Zwangsakte oder Eingriffe von Organen der Landesverwaltung richten, wenn Bürger darin eine Verletzung ihrer Rechte sehen;  (iii) [[Verwaltungsstrafverfahren]]: In vielen Fällen entscheiden die Landesverwaltungsgerichte auch über Berufungen in Verwaltungsstrafverfahren, etwa bei Verkehrsdelikten, Umweltverstößen oder anderen Ordnungswidrigkeiten;  (iv) Disziplinarverfahren und Berufsrecht: Die LVwG sind auch für Disziplinarverfahren gegen bestimmte Berufsgruppen, wie Landesbedienstete oder Angehörige der freien Berufe, zuständig, soweit dies landesrechtlich geregelt ist;  (v) Schutz der [[Grundrechte]]: Die Landesverwaltungsgerichte prüfen, ob Entscheidungen der Landesbehörden den verfassungsmäßig garantierten Grundrechten entsprechen, und sorgen so für die Einhaltung der [[Rechtsstaatlichkeit]] auf Landesebene"}, {"kategorie": "", "text": "Jedes der neun österreichischen Bundesländer verfügt über ein eigenes Landesverwaltungsgericht, das unabhängig arbeitet und in seiner Entscheidungsfindung nicht an Weisungen der Landesverwaltung gebunden ist. Die Entscheidungen der LVwG können in bestimmten Fällen beim [[Verwaltungsgerichtshof]] (VwGH) oder beim [[Verfassungsgerichtshof]] (VfGH) angefochten werden, sofern es sich um grundlegende oder verfassungsrechtlich relevante Fragen handelt."}]'::jsonb, ''),
  ('obalaundesgericht', 'Obalaundesgericht', '', '', '', '', 'Oberlandesgericht', '[{"kategorie": "allg.", "text": "\"Gericht der ordentlichen Gerichtsbarkeit in Österreich, welches die zweite Instanz für [[Zivil-]] und Strafsachen bildet\""}, {"kategorie": "", "text": "Es überprüft Entscheidungen der [[Landesgerichte]] und ist zwischen den erstinstanzlichen Gerichten und dem [[Obersten]] Gerichtshof angesiedelt"}, {"kategorie": "", "text": "Österreich verfügt über vier Oberlandesgerichte, die sich jeweils für bestimmte geografische Regionen des Landes zuständig zeigen: Wien, Graz, Linz und Innsbruck"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten der Oberlandesgerichte:  (i) Berufungs- und Beschwerdeinstanz: Die OLGs sind die Berufungsinstanzen für Zivil- und Strafsachen, die an den Landesgerichten verhandelt wurden. Sie prüfen die Entscheidungen der Landesgerichte auf Rechts- und Sachfehler und können diese bestätigen, abändern oder zur Neuverhandlung an die unteren Instanzen zurückverweisen;  (ii) Überprüfung von erstinstanzlichen Urteilen: Die Oberlandesgerichte überprüfen die Urteile auf ihre Richtigkeit und Gesetzmäßigkeit und stellen so die Rechtssicherheit und Konsistenz in der Rechtsprechung sicher;  (iii) Leitentscheidungen: Die Oberlandesgerichte fällen in einigen Fällen Entscheidungen, die für die untergeordneten Gerichte als Orientierung dienen. So tragen sie zur einheitlichen Rechtsanwendung in ihren jeweiligen Zuständigkeitsbereichen bei;  (iv) Disziplinargerichtsbarkeit: Die OLGs sind auch für Disziplinarverfahren gegen bestimmte Berufsgruppen (etwa Rechtsanwälte und Notare) zuständig und entscheiden in Streitfällen, die sich aus beruflichem Fehlverhalten ergeben;  (v) Verwaltung der Gerichte: Die Präsidenten der Oberlandesgerichte haben zusätzlich Verwaltungsaufgaben und sind für die Organisation und Verwaltung der Gerichte in ihrem Zuständigkeitsbereich verantwortlich"}, {"kategorie": "", "text": "Jedes der vier Oberlandesgerichte ist in Zivilsenate und Strafsenate gegliedert, die jeweils auf die entsprechenden Rechtsgebiete spezialisiert sind. Diese Senate bestehen aus mehreren Berufsrichtern, die im Kollegium über die ihnen vorgelegten Fälle entscheiden"}, {"kategorie": "", "text": "Gegen Entscheidungen der Oberlandesgerichte kann in bestimmten Fällen [[Revision]] oder [[Nichtigkeitsbeschwerde]] beim [[Obersten]] Gerichtshof (OGH) eingelegt werden, der als letzte Instanz entscheidet. Auf diese Weise ergänzen die Oberlandesgerichte das Rechtssystem zwischen den Landesgerichten und dem Obersten Gerichtshof und tragen zur Rechtssicherheit und Konsistenz der österreichischen [[Rechtsprechung]] bei."}]'::jsonb, ''),
  ('laundesgericht', 'Laundesgericht', '', '', '', '', 'Landesgericht', '[{"kategorie": "allg.", "text": "\"Gericht der ordentlichen Gerichtsbarkeit in Österreich, das als erste oder zweite Instanz in [[Zivil-]] und Strafsachen tätig ist\""}, {"kategorie": "", "text": "Es gibt in Österreich 20 Landesgerichte, die jeweils für bestimmte geografische Regionen zuständig sind und eine wichtige Rolle in der [[Rechtsprechung]] zwischen den [[Bezirksgerichten]] und den [[Oberlandesgerichten]] einnehmen"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten der Landesgerichte:  (i) Erste Instanz in schwereren Straf- und Zivilsachen - Die Landesgerichte sind erstinstanzlich zuständig für schwerwiegendere Strafsachen (z. B. Verbrechen mit einer Strafandrohung von mehr als fünf Jahren) und für komplexe Zivilsachen, die nicht in die Zuständigkeit der Bezirksgerichte fallen. Dazu zählen etwa hohe Streitwerte oder spezielle Rechtsgebiete wie Handels- und Gesellschaftsrecht;  (ii) Berufungsinstanz für Bezirksgerichte: In Zivilsachen sind die Landesgerichte die Berufungsinstanzen für Urteile, die von den Bezirksgerichten gefällt wurden. Sie überprüfen diese Urteile auf Fehler in der Rechtsanwendung und können diese bestätigen, abändern oder zur Neuverhandlung an die Bezirksgerichte zurückverweisen;  (iii) [[Geschworenengericht]] und [[Schöffengericht]]: In Strafverfahren mit schweren Verbrechen (z. B. Mord) verhandeln die Landesgerichte entweder mit einem Geschworenengericht oder einem Schöffengericht, um über Schuld und Strafe zu entscheiden;  (iv) Handels- und Kartellgerichtsbarkeit: In einigen Landesgerichten gibt es spezielle Abteilungen, die auf Handels- und Kartellrecht spezialisiert sind, etwa für Wirtschaftsrecht und Unternehmensrecht;  (v) Insolvenzgerichtsbarkeit: Die Landesgerichte sind für Insolvenzverfahren zuständig und übernehmen die rechtliche Abwicklung von Insolvenzen und die Überwachung von Insolvenzverfahren"}, {"kategorie": "", "text": "Ein Landesgericht besteht aus mehreren Abteilungen oder „Senaten“, die jeweils auf bestimmte Rechtsgebiete spezialisiert sind, wie [[Zivilrecht]] oder [[Strafrecht]]. Diese Senate sind mit Berufsrichtern besetzt, die in Kollegien über die vorgelegten Fälle entscheiden"}, {"kategorie": "", "text": "In der Hierarchie der ordentlichen Gerichte stehen die Landesgerichte zwischen den [[Bezirksgerichten]] und den [[Oberlandesgerichten]]. Berufungen gegen Entscheidungen der Landesgerichte werden von den Oberlandesgerichten (OLG) geprüft, die als zweite Instanz fungieren. In Zivilsachen, die in den Bezirksgerichten entschieden wurden, überprüfen die Landesgerichte die Fälle als Berufungsinstanz."}]'::jsonb, ''),
  ('beziaksgericht', 'Beziaksgericht', '', '', '', '', 'Bezirksgericht', '[{"kategorie": "allg.", "text": "\"Gericht der ordentlichen Gerichtsbarkeit in Österreich, das auf erster Instanz für kleinere Zivil- und Strafsachen sowie bestimmte Angelegenheiten der freiwilligen Gerichtsbarkeit zuständig ist\""}, {"kategorie": "", "text": "Österreich verfügt über zahlreiche Bezirksgerichte, die jeweils für einen bestimmten geografischen Bezirk zuständig sind und die niedrigste Instanz in der Gerichtshierarchie darstellen"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten der Bezirksgerichte:  (i) Zivilrechtliche Zuständigkeit: Bezirksgerichte sind für Zivilstreitigkeiten mit geringerem Streitwert (bis zu 15.000 Euro) zuständig. Zu diesen gehören beispielsweise Nachbarschaftsstreitigkeiten, Mietrechtssachen, Familienrecht (wie Scheidungen und Unterhaltsangelegenheiten) sowie Erbschaftsangelegenheiten;  (ii) Strafsachen: In Strafsachen befassen sich die Bezirksgerichte nur mit geringfügigen Delikten, die mit einer maximalen Freiheitsstrafe von einem Jahr oder einer Geldstrafe geahndet werden können, wie etwa Diebstahl geringeren Ausmaßes oder leichte Körperverletzungen;  (iii) Freiwillige Gerichtsbarkeit: Bezirksgerichte sind in vielen Angelegenheiten der freiwilligen Gerichtsbarkeit zuständig, wie etwa bei [[Verlassenschaftsverfahren]] (Abwicklung von Erbschaften), Erwachsenenschutzverfahren (früher Vormundschaft), Pflegschaften und Grundbuchangelegenheiten;  (iv) Mediation und Schlichtung: Bezirksgerichte sind oft erste Anlaufstellen für Mediation oder Schlichtung in zivilrechtlichen Angelegenheiten, insbesondere in Nachbarschaftsstreitigkeiten, um eine außergerichtliche Einigung zu fördern"}, {"kategorie": "", "text": "Bezirksgerichte sind Einzelrichtergerichte, das heißt, die Entscheidungen werden in der Regel von einem einzelnen Richter getroffen. Sie arbeiten in enger Zusammenarbeit mit den übergeordneten [[Landesgerichten]], an die [[Berufungen]] gegen Entscheidungen der Bezirksgerichte gerichtet werden können."}]'::jsonb, ''),
  ('schdrofvafoan', 'Schdrofvafoan', '', '', '', '', 'Strafverfahren', '[{"kategorie": "jur.", "text": "\"gerichtliches Verfahren in Österreich, das zur Ermittlung und Verfolgung von [[Straftaten]] dient\""}, {"kategorie": "", "text": "Ziel des Strafverfahrens ist es, festzustellen, ob eine Person eine strafbare Handlung begangen hat und ob sie dafür zur Verantwortung gezogen werden muss"}, {"kategorie": "", "text": "Das Strafverfahren gliedert sich in mehrere Phasen, von der Einleitung der Ermittlungen bis zur endgültigen Entscheidung im Hauptverfahren und eventuell einer Berufung"}, {"kategorie": "", "text": "Phasen und Ablauf eines Strafverfahrens in Österreich:  (i) Einleitung des Ermittlungsverfahrens: Das Verfahren beginnt mit dem Verdacht auf eine Straftat. Die [[Staatsanwaltschaft]] oder die [[Polizei]] leitet daraufhin ein [[Ermittlungsverfahren]] ein, um Beweise zu sammeln und zu prüfen, ob ein hinreichender Tatverdacht besteht;  (ii) [[Ermittlungsverfahren]]: In dieser Phase werden Beweise gesammelt, Zeugen befragt und gegebenenfalls Verdächtige verhört. Die Staatsanwaltschaft leitet die Ermittlungen und entscheidet am Ende, ob es genug Beweise gibt, um [[Anklage]] zu erheben, oder ob das Verfahren eingestellt wird;  (iii) Anklage und Vorbereitung des Hauptverfahrens: Wenn genügend Beweise vorliegen, erhebt die Staatsanwaltschaft Anklage beim zuständigen Gericht. Der Angeklagte erhält die [[Anklageschrift]] und kann sich auf das Hauptverfahren vorbereiten. In leichten Fällen kann die Staatsanwaltschaft auch einen [[Strafantrag]] stellen, wodurch ein vereinfachtes Verfahren möglich wird;  (iv) Hauptverfahren: Im Hauptverfahren wird der Fall vor Gericht verhandelt. Die Beweise werden geprüft, Zeugen und Sachverständige angehört, und der Angeklagte hat die Möglichkeit, sich zu verteidigen. Das Gericht entscheidet am Ende über die Schuld des Angeklagten und legt gegebenenfalls die Strafe fest;  (v) [[Urteil]]: Nach Abschluss des Hauptverfahrens fällt das Gericht das Urteil, das entweder freisprechend oder verurteilend ausfallen kann. Bei einer Verurteilung wird die Art und Höhe der Strafe festgelegt;  (vi) [[Rechtsmittel]]: Sowohl der Angeklagte als auch die Staatsanwaltschaft können gegen das Urteil Rechtsmittel einlegen, zum Beispiel [[Berufung]] oder [[Nichtigkeitsbeschwerde]]. In diesen Fällen wird das Urteil von einer höheren Instanz geprüft;  (vii) Vollstreckung des Urteils: Wenn das Urteil rechtskräftig wird und keine weiteren Rechtsmittel eingelegt werden, wird die Strafe vollstreckt. Bei einer Freiheitsstrafe erfolgt die Einweisung in eine [[Justizanstalt]], bei einer Geldstrafe die Zahlung oder eventuelle Einbringung durch andere Maßnahmen"}, {"kategorie": "", "text": "Das Strafverfahren in Österreich ist geprägt von der Zusammenarbeit zwischen der [[Staatsanwaltschaft]] und dem [[Gericht]]. Die Staatsanwaltschaft führt die Ermittlungen und erhebt Anklage, während das Gericht die Aufgabe hat, objektiv und unabhängig zu urteilen"}, {"kategorie": "", "text": "Insgesamt dient das Strafverfahren dazu, strafbares Verhalten festzustellen und angemessen zu bestrafen, um die Gerechtigkeit und den Schutz der [[Gesellschaft]] sicherzustellen."}]'::jsonb, ''),
  ('schdrofprozess', 'Schdrofprozess', '', '', '', '', 'Strafprozess', '[{"kategorie": "", "text": "Ziel des Strafverfahrens ist es, festzustellen, ob eine Person eine strafbare Handlung begangen hat und ob sie dafür zur Verantwortung gezogen werden muss"}, {"kategorie": "", "text": "Das Strafverfahren gliedert sich in mehrere Phasen, von der Einleitung der Ermittlungen bis zur endgültigen Entscheidung im Hauptverfahren und eventuell einer Berufung"}, {"kategorie": "", "text": "Phasen und Ablauf eines Strafverfahrens in Österreich:  (i) Einleitung des Ermittlungsverfahrens: Das Verfahren beginnt mit dem Verdacht auf eine Straftat. Die [[Staatsanwaltschaft]] oder die [[Polizei]] leitet daraufhin ein [[Ermittlungsverfahren]] ein, um Beweise zu sammeln und zu prüfen, ob ein hinreichender Tatverdacht besteht;  (ii) [[Ermittlungsverfahren]]: In dieser Phase werden Beweise gesammelt, Zeugen befragt und gegebenenfalls Verdächtige verhört. Die Staatsanwaltschaft leitet die Ermittlungen und entscheidet am Ende, ob es genug Beweise gibt, um [[Anklage]] zu erheben, oder ob das Verfahren eingestellt wird;  (iii) Anklage und Vorbereitung des Hauptverfahrens: Wenn genügend Beweise vorliegen, erhebt die Staatsanwaltschaft Anklage beim zuständigen Gericht. Der Angeklagte erhält die [[Anklageschrift]] und kann sich auf das Hauptverfahren vorbereiten. In leichten Fällen kann die Staatsanwaltschaft auch einen [[Strafantrag]] stellen, wodurch ein vereinfachtes Verfahren möglich wird;  (iv) Hauptverfahren: Im Hauptverfahren wird der Fall vor Gericht verhandelt. Die Beweise werden geprüft, Zeugen und Sachverständige angehört, und der Angeklagte hat die Möglichkeit, sich zu verteidigen. Das Gericht entscheidet am Ende über die Schuld des Angeklagten und legt gegebenenfalls die Strafe fest;  (v) [[Urteil]]: Nach Abschluss des Hauptverfahrens fällt das Gericht das Urteil, das entweder freisprechend oder verurteilend ausfallen kann. Bei einer Verurteilung wird die Art und Höhe der Strafe festgelegt;  (vi) [[Rechtsmittel]]: Sowohl der Angeklagte als auch die Staatsanwaltschaft können gegen das Urteil Rechtsmittel einlegen, zum Beispiel [[Berufung]] oder [[Nichtigkeitsbeschwerde]]. In diesen Fällen wird das Urteil von einer höheren Instanz geprüft;  (vii) Vollstreckung des Urteils: Wenn das Urteil rechtskräftig wird und keine weiteren Rechtsmittel eingelegt werden, wird die Strafe vollstreckt. Bei einer Freiheitsstrafe erfolgt die Einweisung in eine [[Justizanstalt]], bei einer Geldstrafe die Zahlung oder eventuelle Einbringung durch andere Maßnahmen"}, {"kategorie": "", "text": "Das Strafverfahren in Österreich ist geprägt von der Zusammenarbeit zwischen der [[Staatsanwaltschaft]] und dem [[Gericht]]. Die Staatsanwaltschaft führt die Ermittlungen und erhebt Anklage, während das Gericht die Aufgabe hat, objektiv und unabhängig zu urteilen"}, {"kategorie": "", "text": "Insgesamt dient das Strafverfahren dazu, strafbares Verhalten festzustellen und angemessen zu bestrafen, um die Gerechtigkeit und den Schutz der [[Gesellschaft]] sicherzustellen."}]'::jsonb, ''),
  ('zivueuevafoan', 'Zivüüvafoan', '', '', '', '', 'Zivilverfahren', '[{"kategorie": "jur.", "text": "\"gerichtliches Verfahren in Österreich, das der Klärung von privaten Rechtsstreitigkeiten zwischen natürlichen oder juristischen Personen dient\""}, {"kategorie": "", "text": "Es wird durchgeführt, um Ansprüche aus Vertragsstreitigkeiten, Schadenersatzforderungen, Erbrechtsfragen, Familienrechtsangelegenheiten und andere zivilrechtliche Fragen zu entscheiden"}, {"kategorie": "", "text": "Zivilverfahren werden im Rahmen der ordentlichen Gerichtsbarkeit abgewickelt und können sowohl vor den [[Bezirksgerichten]] als auch den [[Landesgerichten]] geführt werden, je nach Art und Streitwert des Falles"}, {"kategorie": "", "text": "Ablauf und Phasen eines Zivilverfahrens in Österreich:  (i) Klageerhebung: Ein Zivilverfahren beginnt mit der Einreichung einer [[Klage]] durch die klagende Partei beim zuständigen [[Gericht]]. Die Klage beschreibt den Sachverhalt, die rechtlichen Ansprüche und die geforderte Leistung, beispielsweise Schadensersatz oder die Erfüllung eines Vertrags;  (ii) Zustellung und Klageerwiderung: Das Gericht stellt die Klage der beklagten Partei zu, die daraufhin Gelegenheit zur Klageerwiderung erhält. In dieser Antwort legt die beklagte Partei ihre Sicht des Sachverhalts dar und kann Gegenargumente und Beweise vorbringen;  (iii) Vorbereitung der Hauptverhandlung: Das Gericht trifft vorbereitende Maßnahmen, sammelt Beweise und lädt gegebenenfalls Zeugen und Sachverständige vor. Ziel ist es, den Sachverhalt umfassend aufzuklären und die Verfahrensdauer zu verkürzen (siehe [[vorbereitende Tagsatzung]]);  (iv) [[Hauptverhandlung]]: In der mündlichen Verhandlung werden alle relevanten Beweise präsentiert, Zeugen und Sachverständige gehört, und die Argumente beider Seiten ausführlich vor dem Richter oder den Richtern erörtert;  (v) [[Urteil]]: Nach Abschluss der [[Beweisaufnahme]] und Anhörung der [[Parteien]] fällt das Gericht das Urteil. Dieses enthält die Entscheidung über die Rechtmäßigkeit der Ansprüche und weist entweder die Klage ab oder gibt ihr ganz oder teilweise statt;  (vi) [[Rechtsmittel]]: Sowohl die klagende als auch die beklagte Partei können das Urteil mit Rechtsmitteln (Berufung, Revision) anfechten, wenn sie die Entscheidung für falsch oder ungerecht halten. Diese werden vor einem höheren Gericht verhandelt;  (vii) Vollstreckung des Urteils: Sobald das Urteil rechtskräftig ist, kann die obsiegende Partei die [[Vollstreckung]] beantragen, wenn die unterlegene Partei der Entscheidung nicht freiwillig nachkommt. Hierzu wird das Gericht tätig, um Ansprüche wie Zahlungen oder Herausgaben durchzusetzen"}, {"kategorie": "", "text": "Das österreichische Zivilverfahren ist durch das Prinzip der [[Parteienöffentlichkeit]] geprägt, das heißt, die Parteien bringen die wesentlichen Informationen und Beweise ein, während das Gericht eine eher passive Rolle übernimmt und als unabhängiger Schiedsrichter fungiert. Zivilverfahren sind damit in erster Linie auf die Klärung von Ansprüchen zwischen privaten Parteien ausgelegt und dienen der Wiederherstellung oder Sicherung individueller Rechte."}]'::jsonb, ''),
  ('zivueueprozess', 'Zivüüprozess', '', '', '', '', 'Zivilprozess', '[{"kategorie": "", "text": "Es wird durchgeführt, um Ansprüche aus Vertragsstreitigkeiten, Schadenersatzforderungen, Erbrechtsfragen, Familienrechtsangelegenheiten und andere zivilrechtliche Fragen zu entscheiden"}, {"kategorie": "", "text": "Zivilverfahren werden im Rahmen der ordentlichen Gerichtsbarkeit abgewickelt und können sowohl vor den [[Bezirksgerichten]] als auch den [[Landesgerichten]] geführt werden, je nach Art und Streitwert des Falles"}, {"kategorie": "", "text": "Ablauf und Phasen eines Zivilverfahrens in Österreich:  (i) Klageerhebung: Ein Zivilverfahren beginnt mit der Einreichung einer [[Klage]] durch die klagende Partei beim zuständigen [[Gericht]]. Die Klage beschreibt den Sachverhalt, die rechtlichen Ansprüche und die geforderte Leistung, beispielsweise Schadensersatz oder die Erfüllung eines Vertrags;  (ii) Zustellung und Klageerwiderung: Das Gericht stellt die Klage der beklagten Partei zu, die daraufhin Gelegenheit zur Klageerwiderung erhält. In dieser Antwort legt die beklagte Partei ihre Sicht des Sachverhalts dar und kann Gegenargumente und Beweise vorbringen;  (iii) Vorbereitung der Hauptverhandlung: Das Gericht trifft vorbereitende Maßnahmen, sammelt Beweise und lädt gegebenenfalls Zeugen und Sachverständige vor. Ziel ist es, den Sachverhalt umfassend aufzuklären und die Verfahrensdauer zu verkürzen (siehe [[vorbereitende Tagsatzung]]);  (iv) [[Hauptverhandlung]]: In der mündlichen Verhandlung werden alle relevanten Beweise präsentiert, Zeugen und Sachverständige gehört, und die Argumente beider Seiten ausführlich vor dem Richter oder den Richtern erörtert;  (v) [[Urteil]]: Nach Abschluss der [[Beweisaufnahme]] und Anhörung der [[Parteien]] fällt das Gericht das Urteil. Dieses enthält die Entscheidung über die Rechtmäßigkeit der Ansprüche und weist entweder die Klage ab oder gibt ihr ganz oder teilweise statt;  (vi) [[Rechtsmittel]]: Sowohl die klagende als auch die beklagte Partei können das Urteil mit Rechtsmitteln (Berufung, Revision) anfechten, wenn sie die Entscheidung für falsch oder ungerecht halten. Diese werden vor einem höheren Gericht verhandelt;  (vii) Vollstreckung des Urteils: Sobald das Urteil rechtskräftig ist, kann die obsiegende Partei die [[Vollstreckung]] beantragen, wenn die unterlegene Partei der Entscheidung nicht freiwillig nachkommt. Hierzu wird das Gericht tätig, um Ansprüche wie Zahlungen oder Herausgaben durchzusetzen"}, {"kategorie": "", "text": "Das österreichische Zivilverfahren ist durch das Prinzip der [[Parteienöffentlichkeit]] geprägt, das heißt, die Parteien bringen die wesentlichen Informationen und Beweise ein, während das Gericht eine eher passive Rolle übernimmt und als unabhängiger Schiedsrichter fungiert. Zivilverfahren sind damit in erster Linie auf die Klärung von Ansprüchen zwischen privaten Parteien ausgelegt und dienen der Wiederherstellung oder Sicherung individueller Rechte."}]'::jsonb, ''),
  ('parteiinoeffentlichkeit', 'Parteiinöffentlichkeit', '', '', '', '', 'Parteienöffentlichkeit', '[{"kategorie": "jur.", "text": "\"Prinzip im österreichischen [[Zivilprozessrecht]], das besagt, dass die [[Parteien]] ([[Kläger]] und [[Beklagter]]) für die Darlegung und Beweiserbringung der Tatsachen verantwortlich sind, die zur Klärung ihres Rechtsstreits notwendig sind\""}, {"kategorie": "", "text": "Im Gegensatz zur [[Offizialmaxime]] (bei der das Gericht eine aktive Rolle in der Ermittlung des Sachverhalts spielt) bedeutet Parteienöffentlichkeit, dass das Gericht im Zivilverfahren eine eher passive Rolle einnimmt und die Parteien selbst ihren Prozess betreiben"}, {"kategorie": "", "text": "Kernpunkte des Prinzips der Parteienöffentlichkeit:  (i) Darlegungspflicht: Die Parteien müssen die Tatsachen darlegen, auf die sie ihre Ansprüche oder Verteidigung stützen. Jede Partei ist verpflichtet, die für ihren Standpunkt wesentlichen Fakten umfassend vorzubringen;  (ii) Beweispflicht: Jede Partei ist dafür verantwortlich, die Beweise für ihre Behauptungen beizubringen. Das Gericht entscheidet nur auf Basis der von den Parteien vorgelegten Beweise und greift nicht eigenständig in die Beweiserhebung ein;  (iii)  Prozessteuerung durch die Parteien: Die Parteien entscheiden, ob und in welchem Umfang sie ihre Ansprüche geltend machen, welche Beweise sie vorlegen und ob sie [[Rechtsmittel]] gegen eine Entscheidung einlegen;  (iv) Verantwortung für den Verfahrensausgang: Das Verfahrensergebnis hängt maßgeblich davon ab, wie gut die [[Parteien]] ihre Position darlegen und ihre [[Beweise]] präsentieren. Wenn eine Partei Tatsachen nicht ausreichend darlegt oder beweist, kann dies zu einem ungünstigen Urteil führen;  (v) Beschleunigung des Verfahrens: Durch die Eigenverantwortung der Parteien für den Sachverhalt und die Beweise kann das Verfahren effizienter und schneller geführt werden"}, {"kategorie": "", "text": "Das Prinzip der Parteienöffentlichkeit fördert die Selbstverantwortung und die Eigeninitiative der Parteien im [[Zivilprozess]] und lässt das [[Gericht]] als neutralen und unparteiischen Schiedsrichter agieren. Es ermöglicht einen fairen Prozessablauf, da beide Parteien die gleiche Möglichkeit haben, ihre Sichtweise darzulegen und Beweise vorzubringen."}]'::jsonb, ''),
  ('offizialmaxime', 'Offizialmaxime', '', '', '', '', 'Offizialmaxime', '[{"kategorie": "jur.", "text": "\"Grundsatz des Verfahrensrechts, insbesondere im [[öffentlichen]] Recht, der besagt, dass das [[Gericht]] oder die zuständige Behörde den Verfahrensablauf von Amts wegen steuert und den Sachverhalt eigenständig ermittelt\""}, {"kategorie": "", "text": "Das bedeutet, dass nicht die [[Parteien]] den Umfang und Inhalt des Verfahrens bestimmen, sondern das Gericht oder die [[Behörde]] selbst aktiv in die Ermittlung und Beweisaufnahme eingreift"}, {"kategorie": "", "text": "Wichtige Merkmale der Offizialmaxime:  (i) Amtswegige Ermittlung: Das Gericht oder die Behörde ist verpflichtet, den Sachverhalt von sich aus (ex officio) vollständig aufzuklären. Dies bedeutet, dass es auch Tatsachen und Beweise berücksichtigt, die von den Parteien möglicherweise nicht vorgebracht wurden;  (ii) Verfahrensleitung durch das Gericht/Behörde: Im Gegensatz zur [[Parteienöffentlichkeit]] im [[Zivilrecht]] übernimmt bei der Offizialmaxime das Gericht oder die Behörde die Führung des Verfahrens. Es bestimmt, welche Beweise erhoben werden und welche Zeugen oder Sachverständigen zu laden sind;  (iii) Schutz öffentlicher Interessen: Die Offizialmaxime wird häufig in Verfahren angewandt, bei denen öffentliche Interessen im Vordergrund stehen, wie z. B. im [[Strafverfahren]], [[Verwaltungsverfahren]] oder [[Familienrecht]]. Das Ziel ist es, eine gerechte und vollständige Aufklärung sicherzustellen, unabhängig davon, was die Parteien selbst einbringen;  (iv) Eigenständige Beweisaufnahme: Das Gericht oder die Behörde trägt die Verantwortung für die vollständige und sachgerechte [[Beweisaufnahme]]. Es greift eigenständig auf alle erforderlichen [[Beweise]] zurück und muss nicht auf die Anträge der Parteien warten;  (v) Unabhängigkeit vom Parteiwillen: Der Verfahrensausgang hängt weniger von den Vorbringen und Beweisen der Parteien ab, sondern vielmehr von der objektiven Feststellung des Sachverhalts durch das Gericht oder die Behörde"}, {"kategorie": "", "text": "Die Offizialmaxime sorgt dafür, dass auch in komplexen Fällen, in denen die Parteien möglicherweise nicht über alle relevanten Informationen oder Beweise verfügen, der Sachverhalt umfassend und gerecht geklärt wird. Sie ist besonders relevant in Verfahren, bei denen neben den individuellen Rechten der Parteien auch öffentliche oder übergeordnete Interessen eine Rolle spielen."}]'::jsonb, ''),
  ('offizialdelikt', 'Offizialdelikt', '', '', '', '', 'Offizialdelikt', '[{"kategorie": "jur.", "text": "Straftat, die von den Strafverfolgungsbehörden ([[Staatsanwaltschaft]] und [[Polizei]]) von Amts wegen verfolgt wird, sobald sie Kenntnis davon erhalten, unabhängig davon, ob das Opfer oder andere Beteiligte einen [[Strafantrag]] gestellt haben§"}, {"kategorie": "", "text": "Die Verfolgung solcher Straftaten erfolgt also „ex officio“ ([[von]] Amts wegen) und ist nicht von der Zustimmung des Opfers oder einer anderen Partei abhängig"}, {"kategorie": "", "text": "Merkmale eines Offizialdelikts:  (i) Amtswegige Verfolgungspflicht: Die Strafverfolgungsbehörden sind gesetzlich verpflichtet, bei einem Offizialdelikt Ermittlungen einzuleiten und die Tat zu verfolgen, sobald sie Kenntnis von der Straftat erlangen – sei es durch Anzeigen, Beobachtungen oder eigene Ermittlungen;  (ii)  Keine Abhängigkeit von Strafanträgen: Anders als bei Antragsdelikten, bei denen ein Strafantrag oder eine Anzeige des Opfers erforderlich ist, wird ein Offizialdelikt unabhängig vom Willen des Opfers verfolgt. Selbst wenn das Opfer keine Strafverfolgung wünscht, muss die Staatsanwaltschaft das Verfahren fortführen;  (iii) Schwere Straftaten: Offizialdelikte sind in der Regel schwerwiegendere [[Straftaten]], die das öffentliche Interesse berühren. Dazu gehören beispielsweise Körperverletzung, Sachbeschädigung, Diebstahl, Raub, Betrug, Mord, Sexualstraftaten oder andere [[Gewaltverbrechen]], die als besonders gefährlich für die [[Gesellschaft]] eingestuft werden;  (iv) Sicherung des öffentlichen Interesses: Die Verfolgungspflicht bei Offizialdelikten dient dem Schutz der Allgemeinheit und der Aufrechterhaltung der [[öffentlichen]] Ordnung, da solche Straftaten über das individuelle Interesse des Opfers hinaus die Sicherheit und Ordnung der Gesellschaft gefährden"}, {"kategorie": "", "text": "Die Unterscheidung zwischen Offizialdelikten und [[Antragsdelikten]] ermöglicht es dem [[Rechtsstaat]], bei schwerwiegenden Straftaten aktiv zum Schutz der Allgemeinheit beizutragen, während bei weniger schwerwiegenden Delikten die persönliche Entscheidung des Opfers stärker berücksichtigt wird."}]'::jsonb, ''),
  ('auntroogsdelikt', 'Auntroogsdelikt', '', '', '', '', 'Antragsdelikt', '[{"kategorie": "jur.", "text": "\"Straftat, die nur dann von den [[Strafverfolgungsbehörden]] verfolgt wird, wenn das Opfer oder eine andere berechtigte Person einen [[Strafantrag]] stellt\""}, {"kategorie": "", "text": "Das bedeutet, dass die [[Staatsanwaltschaft]] und [[Polizei]] erst tätig werden dürfen, wenn das Opfer ausdrücklich den Wunsch äußert, dass die Tat strafrechtlich verfolgt wird"}, {"kategorie": "", "text": "Diese Art von Delikt steht im Gegensatz zum [[Offizialdelikt]], bei dem die [[Strafverfolgung]] von Amts wegen ([[ex officio]]) erfolgt"}, {"kategorie": "", "text": "Merkmale eines Antragsdelikts:  (i) Erfordernis eines Strafantrags: Die Strafverfolgungsbehörden dürfen nur dann Ermittlungen einleiten, wenn das Opfer oder ein anderer Antragsberechtigter einen Strafantrag stellt. Ohne diesen Antrag bleibt die Tat ungeahndet;  (ii) Frist zur Stellung des Antrags: Der Strafantrag muss in der Regel innerhalb einer bestimmten Frist, oft innerhalb von drei Monaten ab Kenntnis der Tat und des Täters, gestellt werden. Nach Ablauf dieser Frist ist eine Strafverfolgung normalerweise nicht mehr möglich;  (iii) Schutz des Opferinteresses: Antragsdelikte betreffen meist weniger schwerwiegende Straftaten, bei denen der Gesetzgeber die Entscheidung über die Strafverfolgung in die Hände des Opfers legen möchte. So kann das Opfer selbst entscheiden, ob es eine strafrechtliche Verfolgung wünscht oder nicht;  (iv) Rücknahme des Antrags: In vielen Fällen kann der Strafantrag bis zu einem bestimmten Punkt im Verfahren zurückgezogen werden, womit die Strafverfolgung in der Regel endet"}, {"kategorie": "", "text": "Beispiele für Antragsdelikte:  (i) Beleidigung, (ii) Hausfriedensbruch, (iii) leichte Körperverletzung, (iv) üble Nachrede, (v) Sachbeschädigung geringeren Ausmaßes"}, {"kategorie": "", "text": "Die Regelung von Antragsdelikten soll das Recht auf Selbstbestimmung des Opfers stärken und unnötige staatliche Eingriffe bei geringeren Straftaten vermeiden, wenn kein Strafverfolgungsinteresse vonseiten des Opfers besteht."}]'::jsonb, ''),
  ('schdrofauntroog', 'Schdrofauntroog', '', '', '', '', 'Strafantrag', '[{"kategorie": "jur.", "text": "\"formelles Gesuch, das eine berechtigte Person – meist das Opfer einer Straftat, aber auch die Staatsanwaltschaft selbst – einbringt, um die strafrechtliche Verfolgung eines bestimmten Delikts einzuleiten\""}, {"kategorie": "", "text": "In Österreich unterscheidet man zwischen einem Strafantrag bei [[Antragsdelikten]], den das Opfer einbringen muss, und einem Strafantrag der Staatsanwaltschaft in gerichtlichen Strafverfahren, insbesondere wenn es sich um ein abgekürztes Verfahren oder um die Einleitung des Hauptverfahrens handelt"}, {"kategorie": "", "text": "In Fällen von Antragsdelikten, wie Beleidigung oder leichten Körperverletzungen, wird der Strafantrag meist vom Opfer gestellt. Erst dann ist die Staatsanwaltschaft verpflichtet, das Verfahren aufzunehmen. Ohne diesen Antrag des Opfers (bzw. der antragsberechtigten Person) würde das Verfahren eingestellt"}, {"kategorie": "", "text": "Aber auch die Staatsanwaltschaft selbst kann bei einfacheren Delikten ohne großes öffentliches Interesse (z. B. geringfügige Straftaten) einen Strafantrag stellen und damit die gerichtliche Bestrafung des Täters beantragen"}, {"kategorie": "", "text": "Diese Form des Strafantrags ist also eine formelle Initiative der Staatsanwaltschaft, unabhängig von der Zustimmung oder dem Antrag eines Opfers."}]'::jsonb, ''),
  ('schoeffe', 'Schöffe', '', '', '', '', 'Schöffe', '[{"kategorie": "jur.", "text": "\"ehrenamtlicher Laienrichter im [[Strafgericht]], der gemeinsam mit Berufsrichtern an der Rechtsprechung teilnimmt\""}, {"kategorie": "", "text": "Schöffen haben keine juristische Ausbildung, sind jedoch gleichberechtigt mit den Berufsrichtern und nehmen an der Entscheidungsfindung über die Schuld und das Strafmaß von Angeklagten teil"}, {"kategorie": "", "text": "Schöffen gibt es in verschiedenen Gerichtssystemen, unter anderem in Deutschland und Österreich, und sie stellen eine Form der Mitwirkung der Bevölkerung an der Justiz dar"}, {"kategorie": "", "text": "Wesentliche Merkmale eines Schöffen:  (i) Ehrenamtliche Tätigkeit: Schöffen üben ihr Amt ehrenamtlich aus und erhalten nur eine geringe Entschädigung;  (ii) Gleichberechtigte Stimmrechte: Sie haben das gleiche Stimmrecht wie Berufsrichter und tragen aktiv zur Urteilsfindung bei, indem sie über Schuld oder Unschuld sowie das Strafmaß abstimmen;  (iii) Beteiligung in [[Strafverfahren]]: Schöffen werden hauptsächlich in Strafverfahren eingesetzt, insbesondere in [[Schöffengerichten]], die für mittlere Straftaten zuständig sind;  (iv) Bürgerliche Perspektive: Die Einbindung von Schöffen soll die Perspektive der allgemeinen Bevölkerung in die [[Rechtsprechung]] einbringen und die Transparenz sowie das Vertrauen in die [[Justiz]] stärken"}, {"kategorie": "", "text": "In Österreich gelten bestimmte Voraussetzungen für Schöffen: Sie müssen das 25. Lebensjahr vollendet haben und dürfen keine Vorstrafen aufweisen. Außerdem müssen sie über die [[österreichische]] Staatsbürgerschaft verfügen und in einem geregelten Beschäftigungsverhältnis stehen oder als unabhängig gelten"}, {"kategorie": "", "text": "Schöffen sind ein wichtiges Bindeglied zwischen Bürgergesellschaft und Justiz, da sie als „Stimme des Volkes“ im Gericht Entscheidungen maßgeblich mittragen."}]'::jsonb, ''),
  ('gschworana', 'Gschworana', '', '', '', '', 'Geschworener', '[{"kategorie": "jur.", "text": "\"Laienrichter, der in bestimmten [[Strafverfahren]] als Mitglied eines [[Geschworenengerichts]] an der Entscheidung über die Schuld eines [[Angeklagten]] beteiligt ist\""}, {"kategorie": "", "text": "Im Gegensatz zu [[Schöffen]], die gemeinsam mit Berufsrichtern entscheiden, treffen Geschworene allein die Schuldspruchentscheidung (also ob der Angeklagte schuldig oder unschuldig ist), während Berufsrichter das Strafmaß festlegen"}, {"kategorie": "", "text": "Wesentliche Merkmale eines Geschworenen:  (i) Laienrichter ohne juristische Ausbildung: Geschworene sind Bürger ohne juristische Fachkenntnisse, die durch eine zufällige Auswahl in das [[Geschworenengericht]] berufen werden;  (ii) Zuständigkeit in schweren Strafsachen: Geschworene kommen in Österreich und anderen Rechtssystemen nur bei besonders schweren Straftaten zum Einsatz, etwa bei Mord, Totschlag oder bestimmten anderen Kapitalverbrechen;  (iii) Schuldspruchentscheidung: Im Geschworenengericht entscheiden die Geschworenen allein über die Schuldfrage, während das Strafmaß von Berufsrichtern festgelegt wird. Hierzu stimmen sie geheim über „schuldig“ oder „nicht schuldig“ ab;  (iv) Einbindung der Bevölkerung: Die Beteiligung von Geschworenen in schwerwiegenden Verfahren soll das Vertrauen der Öffentlichkeit in die Gerichtsbarkeit stärken und sicherstellen, dass Entscheidungen unter Mitwirkung der [[Bürger]] gefällt werden"}, {"kategorie": "", "text": "In Österreich muss ein Geschworener zwischen 25 und 65 Jahre alt sein, über die [[österreichische]] Staatsbürgerschaft verfügen und darf keine einschlägigen Vorstrafen haben"}, {"kategorie": "", "text": "Die Berufung zum Geschworenen ist eine Pflichtaufgabe, der man sich nur aus wichtigen Gründen entziehen kann. Geschworene erhalten für ihre Tätigkeit eine Aufwandsentschädigung"}, {"kategorie": "", "text": "Das Geschworenenwesen ist ein zentraler Bestandteil des österreichischen Justizsystems und wird als wichtige demokratische Institution betrachtet, die Bürgern ermöglicht, in entscheidenden Fragen der [[Rechtsprechung]] mitzuwirken."}]'::jsonb, ''),
  ('zivueuerecht', 'Zivüürecht', '', '', '', '', 'Zivilrecht', '[{"kategorie": "jur.", "text": "\"jener Bereich des Rechts, der die Rechtsbeziehungen zwischen Privatpersonen sowie zwischen Unternehmen und anderen privaten Rechtsträgern regelt\""}, {"kategorie": "", "text": "Im Gegensatz zum [[öffentlichen]] Recht, welches das Verhältnis zwischen [[Staat]] und [[Bürger]] betrifft, bezieht sich das Zivilrecht auf Rechtsangelegenheiten, in denen der Staat in der Regel keine unmittelbare Rolle spielt"}, {"kategorie": "", "text": "Kernbereiche des Zivilrechts:  (i) Personenrecht: Regelt die Rechte und Pflichten von natürlichen und juristischen Personen, einschließlich persönlicher Zustände wie Geschäftsfähigkeit oder Namensrecht;  (ii) Sachenrecht: Bezieht sich auf Eigentum und Besitz sowie auf die Rechte an Sachen, wie z. B. Eigentumserwerb, Eigentumsübertragung und Besitzschutz;  (iii) Schuldrecht: Regelt die Entstehung und Erfüllung von Verpflichtungen und Verträgen zwischen Personen, z. B. Kaufverträge, Dienstleistungsverträge und Werkverträge;  (iv) Familienrecht: Umfasst Rechtsverhältnisse zwischen Familienmitgliedern, wie z. B. Ehe, Scheidung, Kindesunterhalt und Sorgerecht;  (v) Erbrecht: Regelt Fragen der Erbschaft und Vermögensübertragung nach dem Tod, einschließlich der gesetzlichen und testamentarischen [[Erbfolge]]"}, {"kategorie": "", "text": "Merkmale des Zivilrechts:  (i) [[Privatautonomie]]: Das Prinzip, dass die beteiligten Parteien ihre Rechtsverhältnisse im Rahmen der [[Gesetze]] frei gestalten können, insbesondere durch Verträge;  (ii) Gleichordnung der Parteien: Im Zivilrecht begegnen sich die Parteien auf Augenhöhe, im Gegensatz zum öffentlichen Recht, wo der Staat typischerweise eine übergeordnete Rolle einnimmt;  (iii) Rechtsschutz und Durchsetzung: Bei Streitigkeiten im Zivilrecht entscheiden [[Zivilgerichte]], die Urteile fällen und Ansprüche durchsetzen können, wie z. B. Schadensersatzansprüche oder Ansprüche auf die Erfüllung von Verträgen"}, {"kategorie": "", "text": "Das Zivilrecht bildet die Grundlage für das tägliche Leben und wirtschaftliche Handeln, da es alle wesentlichen rechtlichen Beziehungen regelt, die nicht staatliche Eingriffe betreffen. Es schafft somit einen rechtlichen Rahmen für Eigentum, Austausch, Verträge und familiäre Beziehungen, der die Rechte und Pflichten von Privatpersonen schützt und rechtliche Sicherheit gewährleistet."}]'::jsonb, ''),
  ('privatautonomii', 'Privatautonomii', '', '', '', '', 'Privatautonomie', '[{"kategorie": "jur.", "text": "\"grundlegendes Prinzip des [[Zivilrechts]], das besagt, dass jeder Einzelne seine rechtlichen Beziehungen eigenverantwortlich und nach seinen eigenen Vorstellungen gestalten kann\""}, {"kategorie": "", "text": "Die Privatautonomie ist Ausdruck der individuellen Freiheit und Selbstbestimmung und erlaubt es Personen, über ihre Rechtsverhältnisse selbst zu entscheiden, solange sie dabei die geltenden Gesetze einhalten und die Rechte anderer nicht verletzen"}, {"kategorie": "", "text": "Wesentliche Merkmale der Privatautonomie:  (i) Vertragsfreiheit: Das Recht, Verträge nach eigenem Ermessen abzuschließen oder zu verweigern und den Inhalt der Verträge frei zu gestalten. Dies umfasst die Freiheit, Vertragspartner, Vertragsgegenstand und Vertragsbedingungen selbst zu wählen;  (ii) Testierfreiheit: Die Freiheit, durch ein Testament über das eigene Vermögen für den Todesfall zu verfügen und Erben sowie Auflagen und Bedingungen festzulegen;  (iii) Vereinigungsfreiheit: Das Recht, sich mit anderen Personen zu einem bestimmten Zweck zusammenzuschließen und Gesellschaften oder Vereine zu gründen;  (iv) Eigentumsfreiheit: Die Möglichkeit, über das eigene Eigentum frei zu verfügen, es zu nutzen, zu belasten, zu veräußern oder zu vererben"}, {"kategorie": "", "text": "Obwohl die Privatautonomie ein zentrales Prinzip ist, gibt es gewisse rechtliche Grenzen, die zum Schutz von Allgemeininteressen oder schwächeren Vertragspartnern gesetzt werden:  (i) Gesetzliche Vorschriften: Verträge oder Willenserklärungen, die gegen Gesetze oder die guten Sitten verstoßen, sind nichtig oder anfechtbar;  (ii) Schutzvorschriften für Verbraucher: Im Verbraucherschutzrecht gibt es Regelungen, die Verbraucher vor unangemessenen Vertragsbedingungen oder einseitigen Benachteiligungen schützen;  (iii) Mindeststandards im Arbeitsrecht: Arbeitsverträge unterliegen bestimmten Regelungen zum Schutz der Arbeitnehmer, die nicht durch individuelle Vereinbarungen eingeschränkt werden können"}, {"kategorie": "", "text": "Die Privatautonomie ist eine der tragenden Säulen des Zivilrechts und ermöglicht es, die Rechtsverhältnisse flexibel und den individuellen Bedürfnissen entsprechend zu gestalten. Sie stärkt die persönliche Freiheit und Selbstverantwortung und ist eine Grundvoraussetzung für das wirtschaftliche und gesellschaftliche Leben."}]'::jsonb, ''),
  ('testiafreiheit', 'Testiafreiheit', '', '', '', '', 'Testierfreiheit', '[{"kategorie": "jur.", "text": "\"das Recht einer Person, frei über ihr Vermögen für den Todesfall zu verfügen und den Inhalt eines [[Testaments]] nach eigenem Willen festzulegen\""}, {"kategorie": "", "text": "Die Testierfreiheit ist ein Ausdruck der [[Privatautonomie]] im [[Erbrecht]] und ermöglicht es dem [[Erblasser]], seine Vermögensnachfolge individuell zu gestalten, d. h., selbst zu entscheiden, wer sein Vermögen nach seinem Tod erhalten soll"}, {"kategorie": "", "text": "Wesentliche Merkmale der Testierfreiheit:  (i) Freie Erbenwahl: Der Erblasser kann frei wählen, wer seine Erben sein sollen und wie sein Vermögen unter ihnen aufgeteilt wird. Er kann sowohl Verwandte als auch andere Personen oder Institutionen begünstigen;  (ii) Gestaltungsfreiheit: Der Erblasser kann im Testament bestimmte Bedingungen, Auflagen oder Vermächtnisse festlegen, wie z. B. bestimmte Vermögenswerte an bestimmte Personen zu übertragen oder bestimmte Nutzungsrechte zu gewähren;  (iii) Ausschluss von gesetzlichen Erben: Die Testierfreiheit erlaubt es dem Erblasser, gesetzliche Erben auszuschließen oder ihnen nur einen Teil des Vermögens zu hinterlassen, solange der [[Pflichtteil]] gewahrt bleibt"}, {"kategorie": "", "text": "Trotz ihrer Weite ist die Testierfreiheit in Österreich durch gesetzliche Bestimmungen eingeschränkt, um nahestehende Personen zu schützen und eine vollständige Enterbung zu verhindern: (i) Pflichtteilsrecht: Nahe Angehörige, wie Kinder oder Ehepartner, haben oft einen gesetzlichen Anspruch auf einen Mindestanteil des Erbes (Pflichtteil), selbst wenn sie im Testament nicht bedacht wurden;  (ii) Formvorschriften: ein [[Testament]] muss bestimmten formalen Anforderungen genügen, um gültig zu sein (z. B. Schriftform, eigenhändige Unterschrift);  (iii) Sittenwidrigkeit: Bestimmungen, die gegen die guten Sitten oder das Gesetz verstoßen, können nichtig sein"}, {"kategorie": "", "text": "Die Testierfreiheit ist ein zentraler Aspekt des Erbrechts und erlaubt es einer Person, ihre Vermögensnachfolge im Einklang mit persönlichen Beziehungen, Werten und Wünschen zu gestalten. Sie ermöglicht eine individuellere Nachlassregelung als die gesetzliche [[Erbfolge]] und trägt dazu bei, familiäre und persönliche Bindungen im Erbrecht zu berücksichtigen."}]'::jsonb, ''),
  ('schdrofrecht', 'Schdrofrecht', '', '', '', '', 'Strafrecht', '[{"kategorie": "jur.", "text": "\"jener Bereich des Rechts, der sich mit Straftaten und deren Sanktionierung durch den [[Staat]] befasst\""}, {"kategorie": "", "text": "Das Strafrecht legt fest, welches Verhalten als strafbar gilt und welche Strafen für solche Taten vorgesehen sind"}, {"kategorie": "", "text": "Ziel des Strafrechts ist es, [[Rechtsgüter]] (wie Leben, Gesundheit, Eigentum und Sicherheit) zu schützen und durch Bestrafung und Abschreckung gesellschaftliche Ordnung zu wahren"}, {"kategorie": "", "text": "Im Strafrecht sind [[Straftatbestände]] definiert, das heißt, es wird festgelegt, welches Verhalten als Straftat gilt. Beispiele sind Körperverletzung, Diebstahl, Betrug oder Mord"}, {"kategorie": "", "text": "Das Strafrecht sieht für Straftaten bestimmte Sanktionen vor, wie Freiheitsstrafe, Geldstrafe oder gemeinnützige Arbeit. Die Höhe und Art der Strafe richten sich nach der Schwere der Tat und den Umständen des Einzelfalls"}, {"kategorie": "", "text": "Strafrechtliche Sanktionen dürfen nur auf der Grundlage von gesetzlich festgelegten Straftatbeständen verhängt werden. Dies bedeutet, dass eine Handlung nur dann bestraft werden kann, wenn sie zuvor im Gesetz als strafbar festgelegt wurde (Prinzip „nulla poena sine lege“ – keine Strafe ohne Gesetz)"}, {"kategorie": "", "text": "Die Strafe muss sich nach dem Grad der Schuld des Täters richten. Damit eine Person bestraft werden kann, muss sie die Straftat schuldhaft begangen haben, also vorsätzlich oder fahrlässig"}, {"kategorie": "", "text": "Systematik des Strafrechts:  (i) Materielles Strafrecht: Das materielle Strafrecht legt fest, welche Handlungen strafbar sind und welche Strafen vorgesehen sind. Dies umfasst vor allem das [[Strafgesetzbuch]] (StGB), in dem die wesentlichen [[Straftatbestände]] und Sanktionen definiert sind;  (ii) Formelles Strafrecht (Strafprozessrecht): Das Strafprozessrecht regelt das Verfahren zur Aufklärung und Verfolgung von Straftaten, etwa durch [[Polizei]], [[Staatsanwaltschaft]] und [[Gerichte]];  (iii) Nebenstrafrecht: Neben dem Strafgesetzbuch gibt es weitere strafrechtliche Bestimmungen in Sondergesetzen, etwa im Suchtmittelgesetz, der Straßenverkehrsordnung oder im Wirtschaftsrecht"}, {"kategorie": "", "text": "Durch Sanktionen soll die Gesellschaft vor gefährlichem und schädlichem Verhalten geschützt werden. Die Androhung und Durchsetzung von Strafen sollen potenzielle Täter abschrecken und Wiederholungstaten verhindern"}, {"kategorie": "", "text": "Neben der Bestrafung soll das Strafrecht dazu beitragen, den Täter zu resozialisieren und eine Wiedergutmachung für das Opfer zu ermöglichen"}, {"kategorie": "", "text": "Das Strafrecht ist ein Kernbereich des Rechtsstaats und spielt eine zentrale Rolle im Schutz der gesellschaftlichen Ordnung, da es den Rahmen für den Umgang mit kriminellem Verhalten vorgibt und dadurch die Sicherheit und das Vertrauen in die Rechtsprechung fördert."}]'::jsonb, ''),
  ('rechtsgueta', 'Rechtsgüta', '', '', '', '', 'Rechtsgüter', '[{"kategorie": "jur.", "text": "\"bestimmte Werte und Interessen, die durch die [[Rechtsordnung]] geschützt werden, weil sie für das individuelle und gesellschaftliche Leben als besonders schutzwürdig angesehen werden\""}, {"kategorie": "", "text": "Rechtsgüter können sowohl individuelle (persönliche) als auch allgemeine (kollektive) Interessen umfassen und sind zentrale Elemente des [[Strafrechts]] sowie vieler anderer Rechtsbereiche"}, {"kategorie": "", "text": "Der Schutz von Rechtsgütern ist eine Hauptaufgabe des Rechts und bildet die Grundlage für das Verbot und die Sanktionierung bestimmter Handlungen"}, {"kategorie": "", "text": "Wesentliche Rechtsgüter sind:  (i) Leben und körperliche Unversehrtheit: Schutz des Lebens und der körperlichen Integrität eines Menschen. Straftaten wie Mord, Totschlag und Körperverletzung greifen dieses Rechtsgut an;  (ii) Freiheit: Die persönliche Freiheit, wie Bewegungsfreiheit oder Entscheidungsfreiheit, ist ein wichtiges Rechtsgut, das durch [[Straftatbestände]] wie Freiheitsberaubung geschützt wird;  (iii) Eigentum und Vermögen: Eigentum und Vermögen sind als Rechtsgüter vor Diebstahl, Betrug und Sachbeschädigung geschützt;  (iv) Ehre und Persönlichkeitsrecht: Schutz der persönlichen Ehre und der Würde einer Person, etwa durch Gesetze gegen Beleidigung, Verleumdung und üble Nachrede;  (v) Öffentliche Sicherheit und Ordnung: Rechtsgüter, die das allgemeine Wohl und die öffentliche Ordnung schützen, wie der Schutz vor Terrorismus, Drogenhandel oder der Schutz der Umwelt"}, {"kategorie": "", "text": "Typen von Rechtsgütern: (i) Individuelle Rechtsgüter: Diese betreffen das einzelne Individuum und umfassen Werte wie Leben, Freiheit, Eigentum und körperliche Unversehrtheit. Verstöße gegen individuelle Rechtsgüter betreffen direkt die Rechte eines bestimmten Menschen;  (ii) Kollektive Rechtsgüter: Diese betreffen die Allgemeinheit oder den [[Staat]] als Ganzes, z. B. die öffentliche Sicherheit, die Umwelt oder die Funktionsfähigkeit staatlicher Institutionen"}, {"kategorie": "", "text": "Rechtsgüter dienen dazu, die wichtigsten Werte und Interessen in einer [[Gesellschaft]] zu schützen und damit das Zusammenleben zu sichern. Sie bilden die Grundlage des [[Strafrechts]], indem sie die [[Rechtsordnung]] legitimieren, bestimmte Verhaltensweisen zu verbieten und zu sanktionieren"}, {"kategorie": "", "text": "Der Schutz von Rechtsgütern sorgt für die Durchsetzung von sozialen Normen und das Vertrauen der Bürger in die Gerechtigkeit und Stabilität der Rechtsordnung."}]'::jsonb, ''),
  ('zivueuegricht', 'Zivüügricht', '', '', '', '', 'Zivilgericht', '[{"kategorie": "jur.", "text": "\"Gericht, das für die Entscheidung über zivilrechtliche Streitigkeiten zwischen Privatpersonen, Unternehmen oder anderen privaten Rechtsträgern zuständig ist\""}, {"kategorie": "", "text": "Das Zivilgericht befasst sich mit Fällen, die sich auf das Privatrecht (auch [[Zivilrecht]] genannt) beziehen, das die Rechtsverhältnisse zwischen Privatpersonen regelt. Es handelt sich hier um Streitfälle, in denen der [[Staat]] keine strafrechtlichen Maßnahmen ergreift, sondern die beteiligten Parteien ihre privaten Ansprüche und Rechte durchsetzen möchten"}, {"kategorie": "", "text": "Wesentliche Aufgaben eines Zivilgerichts:  (i) Entscheidung über Vertragsstreitigkeiten: Zivilgerichte verhandeln häufig Fälle, die aus Verträgen resultieren, wie z. B. Kauf-, Miet- oder Werkverträge, und entscheiden über deren Auslegung und Durchsetzung;  (ii) Schadensersatzforderungen: Zivilgerichte entscheiden über Ansprüche auf Schadensersatz, etwa nach Unfällen, Vertragsverletzungen oder Vermögensschäden;  (iii) Familienrechtliche Streitigkeiten: In familienrechtlichen Angelegenheiten, wie Scheidung, Sorgerecht oder Unterhalt, ist das Zivilgericht ebenfalls zuständig;  (iv) Erbrechtliche Angelegenheiten: Es regelt Streitigkeiten im Zusammenhang mit [[Erbschaften]], [[Testamenten]] und der Verteilung des [[Nachlasses]];  (v) Eigentums- und Besitzstreitigkeiten: Zivilgerichte befassen sich mit Fragen zum Eigentum, Besitz und deren Übertragung, z. B. bei Immobilien oder wertvollen Gütern"}, {"kategorie": "", "text": "Je nach Höhe des Streitwerts oder der Art des Falls beginnt ein Zivilprozess in einer bestimmten Instanz, z. B. bei einem [[Bezirksgericht]] oder [[Landesgericht]]"}, {"kategorie": "", "text": "Für Fälle, in denen eine Partei mit der Entscheidung unzufrieden ist, gibt es Berufungsgerichte, die das Urteil überprüfen. Diese sind meist [[Landesgerichte]] oder [[Oberlandesgerichte]]"}, {"kategorie": "", "text": "Die Parteien bestimmen den Inhalt und den Umfang des Verfahrens und sind für die Einleitung und Beendigung des Verfahrens verantwortlich (\"Dispositionsmaxime\")"}, {"kategorie": "", "text": "Verfahren vor dem Zivilgericht sollen grundsätzlich mündlich und öffentlich stattfinden, damit Transparenz gewahrt wird"}, {"kategorie": "", "text": "In Zivilprozessen liegt die [[Beweislast]] bei der klagenden Partei, die ihren Anspruch durch [[Beweise]] und [[Zeugenaussagen]] stützen muss"}, {"kategorie": "", "text": "Zivilgerichte spielen eine zentrale Rolle im Rechtssystem, da sie den rechtlichen Rahmen für private Angelegenheiten bieten und gewährleisten, dass Streitigkeiten unter Privatpersonen geordnet und fair gelöst werden. Sie sind entscheidend für den Schutz und die Durchsetzung privater Rechte und schaffen Vertrauen in das rechtliche und wirtschaftliche Umfeld einer [[Gesellschaft]]."}]'::jsonb, ''),
  ('schdrofgricht', 'Schdrofgricht', '', '', '', '', 'Strafgericht', '[{"kategorie": "jur.", "text": "\"Gericht, das sich mit der Verfolgung, Beurteilung und Bestrafung von [[Straftaten]] beschäftigt\""}, {"kategorie": "", "text": "Es entscheidet darüber, ob eine Person für eine Straftat schuldig ist und welche Strafe oder Maßnahme verhängt werden soll\""}, {"kategorie": "", "text": "Das Strafgericht ist somit für die Durchsetzung des [[Strafrechts]] zuständig, das die öffentliche Ordnung und Sicherheit sowie die Einhaltung der [[Gesetze]] gewährleisten soll"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten:  (i) [[Strafverfolgung]] und Schuldfeststellung: Strafgerichte klären, ob der [[Angeklagte]] eine Straftat begangen hat. Sie hören [[Beweise]], [[Zeugen]] und [[Sachverständige]] an und beurteilen, ob die Beweise für eine Verurteilung ausreichen;  (ii) [[Strafzumessung]]: Im Falle einer Verurteilung legt das Strafgericht die Art und Höhe der Strafe fest, etwa durch Freiheitsstrafen, Geldstrafen oder andere Maßnahmen. Die Strafe richtet sich nach der Schwere der Tat, der Schuld des Täters und den Umständen des Einzelfalls;  (iii) Schutz der [[Gesellschaft]]: Strafgerichte sollen die öffentliche Sicherheit schützen, indem sie Straftaten ahnden und präventiv wirken. Sie dienen sowohl der Bestrafung des Täters als auch der Abschreckung möglicher Straftaten in der Gesellschaft"}, {"kategorie": "", "text": "Die Zuständigkeit von Strafgerichten richtet sich in der Regel nach der Schwere der Straftat:  (i) Bezirksgericht: Zuständig für leichtere Straftaten, wie geringfügiger Diebstahl oder geringfügige Körperverletzungen;  (ii) Landesgericht: Zuständig für schwerwiegendere Delikte, wie schwere Körperverletzung oder Betrug in großem Umfang;  (iii) [[Oberlandesgericht]] und Oberster Gerichtshof: Oberste Instanzen, die im Berufungs- oder Revisionsverfahren über die Rechtmäßigkeit und Angemessenheit der Urteile untergeordneter Gerichte entscheiden"}, {"kategorie": "", "text": "Verfahren: Ein [[Strafverfahren]] beginnt in der Regel mit der [[Anklage]] durch die [[Staatsanwaltschaft]], die das öffentliche Interesse vertritt. Die [[Hauptverhandlung]] findet vor dem Strafgericht statt, wobei Berufsrichter oder – in schwereren Fällen – Berufsrichter in Kooperation mit [[Schöffen]] und [[Geschworenen]] entscheiden. Die Beweisführung und das rechtliche Gehör der Verteidigung sind zentrale Bestandteile des Verfahrens"}, {"kategorie": "", "text": "Strafgerichte spielen eine zentrale Rolle im [[Rechtsstaat]], da sie für die Durchsetzung des [[Strafrechts]] und damit für die öffentliche Ordnung und Sicherheit sorgen. Sie stellen sicher, dass Straftäter zur Verantwortung gezogen werden, und tragen durch Strafen und Präventionsmaßnahmen zur Abschreckung und Resozialisierung bei."}]'::jsonb, '')
